window.INDEX=[{"k": "臺灣史　緒論／導論", "t": "為什麼要學歷史", "c": "緒論處理的是整本歷史課的底層問題：我們為什麼要認識過去，又要怎麼認識。第一個理由是向內的——透過家族、社區與族群的來歷，理解自己為何是現在的自己；第二個理由是向外的——透過別人的歷史，理解與我不同的人為何那樣想、那樣活。接著要認識歷史學的兩個核心工具：史料是我們接觸過去的唯一管道，但史料從來不會自己說話，必須經過查證與解讀；歷史解釋則說明了同一件事為什麼會有不同版本。最後，本節整理臺灣史常見的分期方式，替後面六章建立一張時間地圖。", "u": "b1c0.html"}, {"k": "臺灣史　0-1", "t": "歷史與我們的距離", "c": "認識自己，世代傳承；理解他人，多元尊重；歷史學是一種能力，不是一堆答案", "u": "b1c0.html#s01"}, {"k": "臺灣史　0-2", "t": "史料：歷史學的證據", "c": "什麼東西可以當史料；一手史料與二手史料；文字史料以外的世界；史料批判：先問真假，再問意義", "u": "b1c0.html#s02"}, {"k": "臺灣史　0-3", "t": "歷史解釋：同一件事，為什麼有不同說法", "c": "史實、史料與歷史解釋；立場如何決定了被記下來的內容；常見的三個思考陷阱", "u": "b1c0.html#s03"}, {"k": "臺灣史　0-4", "t": "臺灣史的分期與本冊架構", "c": "幾種常見的分期方式；以臺灣島為主體的視角；本冊的四大主題與六章安排", "u": "b1c0.html#s04"}, {"k": "關鍵詞・臺灣史", "t": "史料", "c": "一切能幫助我們認識過去的材料，包含文字、圖像、實物、影音與口述。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "一手史料", "c": "事件當時或當事人直接產生的材料，如檔案、日記、契約；接近現場但不必然客觀。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "二手史料", "c": "後人依據一手史料整理研究而成的作品，如專書、論文、教科書、紀錄片。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "口述歷史", "c": "以訪談方式記錄當事人的經驗與記憶，常用來補足弱勢群體在文字史料中的空白。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "外部考證", "c": "檢驗史料本身的真偽，包括年代、作者、版本與材質是否相符。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "內部考證", "c": "檢驗史料內容的可信度，分析作者立場、寫作動機與內部是否矛盾。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "史實", "c": "有證據支持、確實發生過的事，相對穩定，不因立場而改變。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "歷史解釋", "c": "對史實的因果分析與意義評價，會隨新史料、新方法與新關懷而更新。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "以今律古", "c": "用今日的價值標準直接評判古人，忽略當時的制度與知識條件。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "後見之明", "c": "因為知道結果，誤以為當時的人也能預見未來，忽略歷史的偶然性。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "分期", "c": "把連續的時間切分成若干階段的做法；不同的切法凸顯不同主角，本身即是一種解釋。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "以臺灣為主體", "c": "把臺灣島與島上人群當作敘述的中心，而非某個帝國的邊陲或跳板。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "文化資產", "c": "具有歷史、藝術或科學價值的古蹟、建築、遺址與無形技藝，也是重要的史料。", "u": "b1c0.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "轉型正義", "c": "民主化之後，社會對威權統治時期的人權侵害進行調查、平反與究責的工作。", "u": "b1c0.html#terms"}, {"k": "年代・約 3 萬年前", "t": "長濱文化，舊石器時代晚期人群在臺東海岸活動", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・約 6000 年前", "t": "大坌坑文化出現，被視為南島語族早期文化", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・約 2000 年前", "t": "十三行文化進入金屬器時代，與外界往來", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1624", "t": "荷蘭東印度公司進入大員，臺灣進入有系統的文字紀錄時代", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1626", "t": "西班牙人占領北臺灣雞籠", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1662", "t": "鄭成功驅逐荷蘭人，建立鄭氏政權", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1683", "t": "清朝取得臺灣，次年設臺灣府", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1786", "t": "林爽文事件爆發，清代規模最大的民變", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1860年代", "t": "臺灣開港通商，茶、糖、樟腦進入世界市場", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1885", "t": "清廷下詔臺灣建省", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1895", "t": "《馬關條約》割臺，日本開始殖民統治", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1920", "t": "新民會成立，近代政治社會運動展開", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1945", "t": "第二次世界大戰結束，中華民國政府接收臺灣", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1947", "t": "二二八事件", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1949", "t": "臺灣省戒嚴令生效，中華民國政府遷臺", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1979", "t": "美麗島事件", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1987", "t": "宣布解除戒嚴", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・1996", "t": "首次總統直接民選", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "年代・2000", "t": "首次政黨輪替", "c": "臺灣史　為什麼要學歷史", "u": "b1c0.html#timeline"}, {"k": "臺灣史　第 1 章", "t": "原住民族與外來者的接觸", "c": "本章從史前臺灣談起，說明這座島至少三萬年前就有人群活動，新石器時代以後逐漸形成南島語族的社會。原住民族各族在語言、社會組織與信仰上差異極大，但共同特徵是以部落為單位、沒有跨部落的統一政權。十七世紀荷蘭與西班牙先後在臺灣南北建立據點，他們帶來的不只是槍砲，還有稅制、贌社、教會學校與文字。麻豆社事件與《麻豆協約》顯示部落抵抗的失敗，地方會議則把原本平行的部落納入殖民統治的層級之中。外來者離開後，他們留下的土地觀念、貿易網絡與人口結構，長遠改變了臺灣原住民族社會的處境。", "u": "b1c1.html"}, {"k": "臺灣史　1-1", "t": "史前臺灣與南島語族", "c": "舊石器時代：最早的居民；新石器時代：農業與南島語族；金屬器時代與對外接觸；南島語族與臺灣的位置", "u": "b1c1.html#s11"}, {"k": "臺灣史　1-2", "t": "原住民族的社會與文化", "c": "族群與分布；社會組織的多樣性；信仰與生活", "u": "b1c1.html#s12"}, {"k": "臺灣史　1-3", "t": "荷蘭與西班牙的到來", "c": "大航海時代的東亞；荷蘭人在南臺灣；西班牙人在北臺灣", "u": "b1c1.html#s13"}, {"k": "臺灣史　1-4", "t": "部落抵抗與殖民秩序", "c": "麻豆社事件與《麻豆協約》；地方會議與統治技術；贌社、稅制與傳教；荷蘭統治的結束與遺產", "u": "b1c1.html#s14"}, {"k": "關鍵詞・臺灣史", "t": "長濱文化", "c": "臺東八仙洞的舊石器時代晚期文化，距今約三萬至五千年，以打製石器與採集漁獵為特徵。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "大坌坑文化", "c": "距今約六、七千年前的新石器時代早期文化，以繩紋陶著稱，被視為南島語族祖先型文化。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "十三行文化", "c": "新北八里的金屬器時代文化，出土煉鐵遺跡與外來貿易品，顯示臺灣已進入區域交換網絡。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "南島語族", "c": "世界分布最廣的語族之一，範圍涵蓋馬達加斯加至復活節島；臺灣是其分布最北界。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣原鄉說", "c": "依據臺灣南島語言分化程度極高，推論臺灣可能是南島語族向外擴散起點之一的學說。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "年齡階級", "c": "阿美族、卑南族等依年齡將男子分組，各級承擔防衛、勞役與祭儀任務的社會制度。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "gaya", "c": "泰雅族、賽德克族的祖訓規範，涵蓋倫理、禁忌與儀式，違反者被視為會招致集體災禍。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "熱蘭遮城", "c": "荷蘭在大員（今臺南安平）興建的城堡，是荷治時期的統治與貿易中心。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "麻豆社事件", "c": "1629 年荷蘭士兵在麻豆社附近遭溺殺的衝突，重創荷蘭威信，導致 1635 年的報復出兵。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "《麻豆協約》", "c": "1635 年麻豆社戰敗後與荷蘭簽訂的條約，確立部落臣屬於荷蘭東印度公司的關係，成為各社締約範本。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "地方會議", "c": "1641 年起荷蘭召集各村社長老的集會，授予藤杖並宣達政令，把部落納入殖民行政層級。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "贌社", "c": "荷蘭自 1644 年起實施，由商人競標取得與特定部落的獨家交易權，政府收取標金。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "新港文書", "c": "以羅馬字拼寫西拉雅語的文書，多為土地契約，俗稱番仔契，部分沿用至十九世紀。", "u": "b1c1.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "大肚王", "c": "十七世紀臺灣中部跨部落聯盟的領袖，1645 年與荷蘭締約歸順但仍保有相當自治。", "u": "b1c1.html#terms"}, {"k": "年代・約 3 萬年前", "t": "長濱文化，臺灣目前已知最早的史前文化", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・約 6000 年前", "t": "大坌坑文化，南島語族早期文化", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・約 5000 年前", "t": "卑南文化，出土石板棺與玉器", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・約 2000 年前", "t": "十三行文化進入金屬器時代，與外界貿易", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・十六世紀", "t": "歐洲船隻航經臺灣，「福爾摩沙」之名見於西方文獻", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1622", "t": "荷蘭東印度公司占領澎湖並築城", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1624", "t": "荷蘭轉進大員，興建熱蘭遮城", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1626", "t": "西班牙占雞籠社寮島，築聖薩爾瓦多城", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1628", "t": "西班牙占淡水，築聖多明哥城", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1629", "t": "麻豆社事件，荷蘭士兵遭溺殺", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1635", "t": "荷蘭攻破麻豆社，簽訂《麻豆協約》", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1636", "t": "荷蘭傳教士在新港社設學校，以羅馬字拼寫新港語", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1641", "t": "荷蘭首次召開地方會議，授予村社長老藤杖", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1642", "t": "荷蘭驅逐西班牙人，取得北臺灣", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1644", "t": "荷蘭開始實施贌社制度", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1645", "t": "中部大肚王與荷蘭締約歸順", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1652", "t": "郭懷一事件，漢人反荷起事失敗", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1662", "t": "荷蘭投降撤離，鄭成功取得臺灣", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・1994", "t": "憲法增修條文將「山胞」正名為「原住民」", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "年代・2014", "t": "拉阿魯哇族、卡那卡那富族獲認定，原住民族增為 16 族", "c": "臺灣史　原住民族與外來者的接觸", "u": "b1c1.html#timeline"}, {"k": "臺灣史　第 2 章", "t": "漢人移民與多元族群社會", "c": "本章處理臺灣如何從原住民族社會，轉變為以漢人為多數的多元族群社會。澎湖自元代即設巡檢司，但明初海禁反而使臺灣長期處於官方視野之外，成為走私與私人勢力活動的空間。十七世紀顏思齊、鄭芝龍與荷蘭人先後招募漢人來臺，開啟大規模移民。清代雖有渡臺禁令，移民仍持續湧入，形成男多女少、地緣認同強烈、械鬥頻仍的移墾社會，十九世紀後才逐漸轉為安土重遷的定居社會。漢人拓墾同時壓縮了平埔族群的土地與生存空間，迫使他們遷徙或改變生活方式。戰後外省移民、一九九〇年代以後的新住民與移工，則讓這座島的族群圖像繼續增添新的層次。", "u": "b1c2.html"}, {"k": "臺灣史　2-1", "t": "從澎湖到臺灣：漢人的早期足跡", "c": "澎湖：官方最早納入的一步；海商、海盜與臺灣；荷治與鄭氏時期的移民", "u": "b1c2.html#s21"}, {"k": "臺灣史　2-2", "t": "清代的移民政策與移墾社會", "c": "渡臺禁令與偷渡；移墾社會的特徵；械鬥與民間結社；從移墾社會走向定居社會", "u": "b1c2.html#s22"}, {"k": "臺灣史　2-3", "t": "原漢關係與平埔族群的處境", "c": "番界、番大租與通事；平埔族群的遷徙與轉變；拓墾前線的推進", "u": "b1c2.html#s23"}, {"k": "臺灣史　2-4", "t": "族群融合與當代的新移民", "c": "融合的痕跡；戰後的族群結構；新住民與移工；多元族群的當代課題", "u": "b1c2.html#s24"}, {"k": "關鍵詞・臺灣史", "t": "澎湖巡檢司", "c": "元代設於澎湖的行政機構，是中國王朝首次在澎湖設官；範圍不及臺灣本島。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "渡臺禁令", "c": "1684 年起清朝限制人民渡臺的規定，須申請許可、不得攜眷，一度禁粵人來臺；1875 年全面廢除。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "羅漢腳", "c": "清代臺灣單身、無恆產、四處遊走的男性移民，是移墾社會治安問題的來源之一。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "分類械鬥", "c": "依祖籍分類而起的集體武裝衝突，常見漳泉拚與閩粵拚，反映官府控制薄弱與缺乏仲裁機制。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "頂下郊拚", "c": "1853 年臺北泉州人內部的械鬥，同安人戰敗遷往大稻埕，間接促成大稻埕興起。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "墾首", "c": "向官府請領墾照、再招佃開墾的拓墾主持者，是清代土地開發的核心角色。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "一田多主", "c": "清代臺灣土地出現大租戶、小租戶與現耕佃農多層權利並存的結構。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "番大租", "c": "漢人承墾原住民族土地時繳納的地租，原意在保障原住民地權，實際上多因典賣欺瞞而流失。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "土牛溝", "c": "清廷為隔離漢番而挖溝堆土形成的界線，配合紅、藍、紫線標示的番界，隨拓墾推進屢次東移。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "通事", "c": "負責官府、漢人與原住民族部落之間溝通與收租的中介者，權力大且易生舞弊。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "屯番制度", "c": "1790 年林爽文事件後設立，徵調熟番為屯丁守衛番界，並撥給養贍埔地作為報酬。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "義民", "c": "民變或械鬥時協助官方作戰的地方武力，在客家社會發展出義民爺信仰。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "新住民", "c": "一九九〇年代以後來自東南亞與中國大陸的婚姻移民及其家庭，是臺灣族群圖像的新成員。", "u": "b1c2.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "四大族群", "c": "解嚴後流行的分類，指原住民族、閩南、客家與外省；是簡化架構，無法涵蓋所有群體。", "u": "b1c2.html#terms"}, {"k": "年代・約 1281", "t": "元朝在澎湖設置巡檢司", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・十四世紀末", "t": "明初實施海禁，廢澎湖巡檢司並強制居民內遷", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1621", "t": "顏思齊率眾入臺，招募漢人來墾", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1624", "t": "荷蘭治臺，招攬漢人從事稻作與蔗作", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1628", "t": "鄭芝龍接受明朝招撫", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1661", "t": "鄭氏政權來臺，實施軍屯", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1684", "t": "清設臺灣府，頒布渡臺禁令", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1709", "t": "陳賴章墾號請墾大佳臘，開發臺北盆地", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1719", "t": "施世榜完成八堡圳，彰化平原水田化", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1786", "t": "林爽文事件，義民組織大量出現", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1790", "t": "清廷設立屯番制度，徵調熟番守界", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1796", "t": "吳沙率眾入墾蛤仔難（今宜蘭）", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1823", "t": "中部平埔族群集體遷往埔里盆地", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1853", "t": "臺北頂下郊拚，同安人遷往大稻埕", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1875", "t": "沈葆楨奏請廢除渡臺禁令與番界封禁", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1949", "t": "中華民國政府遷臺，大量軍民隨之來臺", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1989", "t": "政府開始引進外籍勞工", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・1994", "t": "憲法增修條文將「山胞」正名為「原住民」", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・2005", "t": "《原住民族基本法》公布", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "年代・2017", "t": "《原住民族語言發展法》公布，族語列為國家語言", "c": "臺灣史　漢人移民與多元族群社會", "u": "b1c2.html#timeline"}, {"k": "臺灣史　第 3 章", "t": "現代國家的形塑", "c": "本章追蹤統治臺灣的政權如何一步步把這座島「國家化」。鄭氏政權首度在臺灣建立漢人式的行政與教育體系；清朝原本消極治臺，直到牡丹社事件與清法戰爭的外力衝擊，才轉為積極經營並在 1885 年建省。日本殖民統治帶來現代國家的完整配備：戶口、地籍、警察、法律、鐵路與統計，但這些制度同時也是控制的工具，臺灣人並未取得平等的政治地位。戰後臺灣從行政長官公署改制為省，1949 年後中華民國政府遷臺，臺、澎、金、馬在冷戰格局下才實際成為同一個治理單位；地方自治則在威權體制的縫隙中逐步開展。", "u": "b1c3.html"}, {"k": "臺灣史　3-1", "t": "鄭氏政權與清朝的臺灣", "c": "鄭氏政權的建制；清朝取得臺灣與治臺原則；行政區的演變；民變與社會控制", "u": "b1c3.html#s31"}, {"k": "臺灣史　3-2", "t": "從消極到積極：晚清的轉變", "c": "開港通商與外力進入；牡丹社事件與沈葆楨的變革；清法戰爭與臺灣建省；割臺與乙未之役", "u": "b1c3.html#s32"}, {"k": "臺灣史　3-3", "t": "日本殖民統治的體制", "c": "總督府與法律基礎；統治技術與基礎調查；武裝抗日到體制內抗爭；地方制度與戰時體制", "u": "b1c3.html#s33"}, {"k": "臺灣史　3-4", "t": "戰後臺澎金馬成為一體", "c": "接收與行政長官公署；冷戰下的臺澎金馬；地方自治的開展與限制；國家體制的重整", "u": "b1c3.html#s34"}, {"k": "關鍵詞・臺灣史", "t": "承天府", "c": "1661 年鄭成功在赤崁設置的行政中心，下轄天興、萬年二縣，是臺灣首見的漢人式地方行政體制。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "全臺首學", "c": "臺南孔廟的別稱。陳永華建議鄭經興學，1666 年落成，兼具祭孔與教育、科舉功能。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "棄留之爭", "c": "1683 年清廷內部關於是否保留臺灣的爭論，施琅主張臺灣為東南屏障，最終清廷決定設府治理。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "班兵制", "c": "清代臺灣駐軍自福建各營輪調而來、定期換防的制度，目的在防止軍隊與地方勢力結合。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "開山撫番", "c": "牡丹社事件後清廷推動的政策，開闢通往後山的道路並進入原住民族領域，手段包含武力征討與設隘駐軍。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "《北京專約》", "c": "1874 年牡丹社事件後清日所簽，清廷承認日本出兵為保民義舉並支付款項，間接承認琉球屬日。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "億載金城", "c": "沈葆楨在安平興建的西式砲臺（二鯤鯓砲臺），象徵晚清海防觀念的轉變。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣民主國", "c": "1895 年為抗拒割臺而成立，推唐景崧為總統、年號永清、藍地黃虎旗，數月後瓦解。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "《六三法》", "c": "1896 年施行，授予臺灣總督發布律令的權力，是日本在臺特別統治的法源基礎。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "保甲制度", "c": "1898 年實施，以十戶為甲、十甲為保，住民相互監視連坐，配合警察維持治安。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "土地調查", "c": "1898-1905 年總督府進行的全臺地籍清查，廢除大租戶並確立地權，使稅收大幅增加。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "五州二廳", "c": "1920 年地方制度改革後的行政區劃，1926 年增澎湖廳成為五州三廳。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "行政長官公署", "c": "1945 至 1947 年統治臺灣的機關，長官集大權於一身，二二八事件後改組為臺灣省政府。", "u": "b1c3.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "戰地政務", "c": "1956 至 1992 年金門、馬祖實施的軍事管制體制，民政由軍方主導，比本島戒嚴延續更久。", "u": "b1c3.html#terms"}, {"k": "年代・1661", "t": "鄭成功入臺，設承天府與天興、萬年二縣", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1662", "t": "荷蘭投降撤離，鄭成功病逝", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1664", "t": "鄭經改東都為東寧，二縣升為州", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1683", "t": "施琅澎湖海戰獲勝，鄭克塽降清", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1684", "t": "清設臺灣府，隸屬福建省", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1721", "t": "朱一貴事件", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1723", "t": "增設彰化縣、淡水廳", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1786-1788", "t": "林爽文事件，清代臺灣最大民變", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1812", "t": "設噶瑪蘭廳", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1858-1860", "t": "《天津條約》《北京條約》，臺灣開港通商", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1871", "t": "琉球宮古島船民漂流至八瑤灣遇害", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1874", "t": "牡丹社事件，沈葆楨來臺辦理防務", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1884-1885", "t": "清法戰爭，法軍攻基隆、滬尾並占澎湖", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1885", "t": "清廷下詔臺灣建省，1887 年正式分治", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1895", "t": "《馬關條約》割臺，臺灣民主國成立與瓦解", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1896", "t": "《六三法》施行，總督取得律令制定權", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1920", "t": "地方制度改為五州二廳", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1945", "t": "日本投降，設臺灣省行政長官公署", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1949", "t": "古寧頭戰役，中華民國政府遷臺", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "年代・1992", "t": "金門、馬祖終止戰地政務", "c": "臺灣史　現代國家的形塑", "u": "b1c3.html#timeline"}, {"k": "臺灣史　第 4 章", "t": "追求自治與民主的軌跡", "c": "本章處理臺灣人爭取政治參與的百年歷程。日治時期，受過新式教育的臺灣人放棄武裝路線，改以結社、請願、辦報與演講等合法方式爭取自治，議會設置請願運動與臺灣文化協會是兩大主軸，後來又分化出農民、勞工與左翼路線。戰後初期的期待因接收失政而破滅，二二八事件與長達三十八年的戒嚴，使公共討論長期噤聲。一九七〇年代起黨外運動在地方選舉中累積能量，經歷中壢事件與美麗島事件的挫折與擴散，終於推動解嚴、國會全面改選與總統直選，完成政治體制的民主化。", "u": "b1c4.html"}, {"k": "臺灣史　4-1", "t": "日治時期的政治社會運動", "c": "從武裝到議會路線；新民會與議會設置請願運動；臺灣文化協會與啟蒙運動；政黨、農組與多元路線", "u": "b1c4.html#s41"}, {"k": "臺灣史　4-2", "t": "戰後初期與二二八事件", "c": "期待與失望；二二八事件的爆發與鎮壓；戒嚴與白色恐怖", "u": "b1c4.html#s42"}, {"k": "臺灣史　4-3", "t": "黨外運動與民主化", "c": "縫隙中的反對力量；中壢事件與美麗島事件；解嚴與體制轉型；民主鞏固與未竟之路", "u": "b1c4.html#s43"}, {"k": "關鍵詞・臺灣史", "t": "新民會", "c": "1920 年在東京成立的臺灣人政治團體，發行《臺灣青年》，是近代臺灣政治運動的起點。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣議會設置請願運動", "c": "1921 至 1934 年共 15 次，向日本帝國議會請求設立具立法與預算審議權的臺灣議會。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "治警事件", "c": "1923 年蔣渭水等人籌組臺灣議會期成同盟會，遭以違反治安警察法檢舉入獄，反使運動聲勢擴大。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣文化協會", "c": "1921 年成立的啟蒙團體，以演講會、讀報社、夏季學校與美臺團電影隊推廣新知，1927 年因路線之爭分裂。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "美臺團", "c": "臺灣文化協會的電影放映隊，以巡迴放映與辯士解說的方式在鄉間進行文化啟蒙。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣民眾黨", "c": "1927 年蔣渭水等人創立，臺灣第一個近代政黨，1931 年遭總督府解散。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣農民組合", "c": "1926 年簡吉等人成立，串連全島農民抗爭，源頭可追溯至 1925 年二林蔗農事件。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣地方自治聯盟", "c": "1930 年成立，專注爭取地方自治與選舉權，是日治政治運動中最溫和的一支，1937 年解散。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "二二八事件", "c": "1947 年因查緝私菸衝突引爆的全島性抗爭與鎮壓，造成大量傷亡與長期的社會恐懼。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "白色恐怖", "c": "戒嚴時期以《懲治叛亂條例》等法令，透過軍事審判大規模壓制異議的統治狀態。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "黨外", "c": "戒嚴時期禁止組黨，反對人士以非執政黨身分參選並串連，逐步形成的政治勢力。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "美麗島事件", "c": "1979 年 12 月 10 日《美麗島》雜誌社在高雄舉行人權日遊行，與警方衝突後多人遭軍法審判。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "野百合學運", "c": "1990 年三月學生靜坐中正紀念堂，提出解散國大、廢除臨時條款等四大訴求，推動政治改革。", "u": "b1c4.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "轉型正義", "c": "民主化後對威權時期人權侵害進行真相調查、平反、賠償與制度改革的工作。", "u": "b1c4.html#terms"}, {"k": "年代・1914", "t": "臺灣同化會成立，翌年遭解散", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1918", "t": "東京臺灣留學生發起六三法撤廢運動", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1920", "t": "新民會成立，《臺灣青年》創刊", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1921", "t": "臺灣議會設置請願運動開始；臺灣文化協會成立", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1923", "t": "治警事件，蔣渭水等人遭檢舉入獄", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1925", "t": "二林蔗農事件", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1926", "t": "臺灣農民組合成立", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1927", "t": "臺灣文化協會分裂；臺灣民眾黨成立", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1930", "t": "臺灣地方自治聯盟成立", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1935", "t": "臺灣首次舉行地方選舉", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1947", "t": "二二八事件", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1949", "t": "臺灣省戒嚴令生效", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1960", "t": "雷震案，籌組中國民主黨失敗", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1977", "t": "中壢事件", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1979", "t": "美麗島事件", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1986", "t": "民主進步黨成立", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1987", "t": "宣布解除戒嚴", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1990", "t": "三月學運（野百合學運）", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1991", "t": "終止動員戡亂時期，廢止臨時條款", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "年代・1996", "t": "首次總統直接民選", "c": "臺灣史　追求自治與民主的軌跡", "u": "b1c4.html#timeline"}, {"k": "臺灣史　第 5 章", "t": "經濟活動與對外貿易", "c": "本章以「臺灣賣什麼給世界」為線索，貫穿四百年的經濟史。十七世紀的臺灣是東亞轉口貿易的中繼站，荷蘭人在此串連中國生絲、日本白銀與東南亞香料，鹿皮與蔗糖則是本地的主力商品。清代兩岸形成米糖北運、布匹日用品南來的區域分工，由郊商主導；開港之後茶、糖、樟腦把臺灣直接接上世界市場，經濟重心也隨之北移。日治時期臺灣被塑造成日本的糖業與米作基地，並建立起現代化的基礎設施與金融制度。戰後歷經進口替代、出口擴張、十大建設，最後走向以半導體為核心的科技產業，臺灣始終是一個高度依賴外貿、對國際景氣極為敏感的經濟體。", "u": "b1c5.html"}, {"k": "臺灣史　5-1", "t": "大航海時代的轉口貿易", "c": "東亞海域的供需結構；荷蘭的貿易經營；濱田彌兵衛事件與日本鎖國；鄭氏政權的以商養戰", "u": "b1c5.html#s51"}, {"k": "臺灣史　5-2", "t": "清代的兩岸貿易與開港", "c": "對渡口岸與區域分工；開港通商與世界市場；茶、糖、樟腦的故事；經濟重心的北移", "u": "b1c5.html#s52"}, {"k": "臺灣史　5-3", "t": "日治時期的殖民地經濟", "c": "建立資本主義的基礎；糖業帝國；米作與水利；從農業臺灣到工業化", "u": "b1c5.html#s53"}, {"k": "臺灣史　5-4", "t": "戰後經濟的轉型", "c": "重建與土地改革；進口替代與出口擴張；十大建設與產業升級；全球化下的臺灣經濟", "u": "b1c5.html#s54"}, {"k": "關鍵詞・臺灣史", "t": "轉口貿易", "c": "商品在第三地轉手再運往目的地的貿易型態；十七世紀臺灣因位置優越而成為東亞的重要中繼站。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "朱印船", "c": "十七世紀初日本核發許可證的海外貿易商船，臺灣是其重要停靠地之一。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "濱田彌兵衛事件", "c": "1628 年日本朱印船船長挾持荷蘭大員長官訥茨的衝突，導致日荷貿易一度中斷。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "鎖國令", "c": "1633 年起德川幕府陸續頒布，限制日本人出海與外船來航，日本商人自此退出臺灣。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "以商養戰", "c": "鄭氏政權以海上貿易的利潤支撐軍事開支的經營方式。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "對渡制度", "c": "清廷指定特定口岸互相通航的管理制度，如鹿耳門對廈門、鹿港對蚶江、八里坌對五虎門。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "郊", "c": "清代同業或同地商人組成的商業團體，兼具經商與地方公共事務的功能，如臺南三郊、鹿港八郊。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "買辦", "c": "開港後洋行與本地商人之間的中介者，藉此累積資本，形成新興商人階層。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "原料採取區域", "c": "1905 年製糖場取締規則劃定，蔗農只能將甘蔗賣給指定會社，不得自由選擇買主。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "蓬萊米", "c": "日治時期培育、適合臺灣栽種的日本型稻米，1926 年正式命名，為對日輸出的重要品項。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "嘉南大圳", "c": "八田與一設計、1930 年完工的水利工程，使嘉南平原大片看天田變為水田，並採三年輪作給水。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "米糖相剋", "c": "米作與蔗作爭奪土地、水源與勞力所形成的緊張關係，蔗農處境通常較為不利。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "進口替代", "c": "以高關稅與外匯管制保護國內產業、減少進口的政策，臺灣於一九五〇年代採行。", "u": "b1c5.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "加工出口區", "c": "結合免稅、簡化通關與廉價勞力的外銷專區，1966 年高雄加工出口區為全球最早設立者之一。", "u": "b1c5.html#terms"}, {"k": "年代・1624", "t": "荷蘭東印度公司進入大員，建立轉口貿易基地", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1626", "t": "西班牙人占雞籠，試圖經營北臺灣貿易", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1628", "t": "濱田彌兵衛事件，日荷貿易中斷", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1633", "t": "德川幕府開始頒布鎖國令", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1684", "t": "清設鹿耳門對渡廈門", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1784", "t": "開放鹿港對渡蚶江", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1788", "t": "開放八里坌對渡五虎門", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1860年代", "t": "臺灣開港通商，茶、糖、樟腦成為出口主力", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1865", "t": "英商杜德引進安溪茶苗，推廣烏龍茶", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1899", "t": "臺灣銀行成立，統一貨幣", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1900", "t": "臺灣製糖株式會社成立", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1905", "t": "製糖場取締規則劃定原料採取區域", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1908", "t": "縱貫鐵路全線通車", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1926", "t": "蓬萊米正式命名", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1930", "t": "嘉南大圳完工", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1934", "t": "日月潭水力發電工程完工", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1949", "t": "幣制改革，發行新臺幣；實施三七五減租", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1953", "t": "實施耕者有其田", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1966", "t": "高雄加工出口區成立", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "年代・1980", "t": "新竹科學工業園區成立", "c": "臺灣史　經濟活動與對外貿易", "u": "b1c5.html#timeline"}, {"k": "臺灣史　第 6 章", "t": "宗教發展與藝文活動", "c": "本章從信仰與藝文兩條線索，看臺灣文化的多樣性如何形成。原住民族以泛靈與祖靈信仰維繫社會秩序；漢人移民把原鄉守護神帶過黑水溝，廟宇逐漸從同鄉聚點變成地方社會的整合中心。西方宗教在荷西時期短暫進入，十九世紀後隨開港再度來臺，以醫療與教育深刻影響臺灣社會。日治後期的皇民化政策壓迫傳統信仰與民間戲曲，戰後則在戒嚴與解嚴的轉折中走向多元。藝文方面，從沈光文的東吟社、日治新文學與美術運動，到戰後的鄉土文學論戰與新電影，臺灣創作者始終在追問：我們要用誰的語言、畫誰的風景、說誰的故事。", "u": "b1c6.html"}, {"k": "臺灣史　6-1", "t": "原住民族信仰與漢人民間信仰", "c": "泛靈與祖靈的世界；漢人移民的原鄉信仰；廟宇與地方社會；儒學、書院與科舉", "u": "b1c6.html#s61"}, {"k": "臺灣史　6-2", "t": "西方宗教的傳入", "c": "荷西時期的第一波；十九世紀的第二波；教會帶來的社會影響", "u": "b1c6.html#s62"}, {"k": "臺灣史　6-3", "t": "日治時期的宗教政策與新文化", "c": "從尊重舊慣到皇民化；戰時的文化統制；新文學運動；美術與音樂的新視野", "u": "b1c6.html#s63"}, {"k": "臺灣史　6-4", "t": "戰後宗教多元與文化本土化", "c": "戰後的宗教發展；戰後文學的變化；美術、電影與大眾文化；本土化與多元文化的制度化", "u": "b1c6.html#s64"}, {"k": "關鍵詞・臺灣史", "t": "泛靈信仰", "c": "相信萬物皆有靈性的信仰型態，是多數臺灣原住民族宗教觀的基礎。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "祭祀圈", "c": "以某座主廟為中心、共同出資祭祀的地域範圍，是理解清代地方社會整合的重要概念。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "分香與進香", "c": "從祖廟分出香火建立新廟稱分香；新廟定期回祖廟謁祖稱進香，兩者把各地廟宇串成網絡。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "義民信仰", "c": "客家社會祭祀民變中協助官方作戰的死難者，1788 年乾隆賜「褒忠」匾額後地位確立。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "東吟社", "c": "1685 年沈光文與諸羅知縣季麒光等人組成，一般視為臺灣第一個詩社。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "白話字", "c": "教會以羅馬拼音書寫臺語的系統，用於出版聖經與刊物，使不識漢字者也能閱讀。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "《臺灣府城教會報》", "c": "1885 年巴克禮以白話字創辦，是臺灣最早的報紙，也是重要的社會史料。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "寺廟整理運動", "c": "一九三〇年代末皇民化時期廢併寺廟、焚毀神像的政策，以新竹州一帶最為激烈。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "正廳改善", "c": "皇民化時期要求家戶撤去祖先牌位與神像、改設神棚供奉日本神祇的措施。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "新舊文學論戰", "c": "1924 年張我軍批判舊詩壇後展開的論爭，確立白話文在臺灣新文學中的主導地位。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺灣話文論戰", "c": "1930 年黃石輝提倡以臺灣話寫作所引發的論爭，觸及書寫語言與文化認同問題。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "臺展", "c": "1927 年開辦的臺灣美術展覽會，是臺灣近代美術的重要舞臺，首屆有「臺展三少年」之稱。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "鄉土文學論戰", "c": "1977 至 1978 年關於文學應面向世界或回歸本地土地的論爭，促成文學視野的本土轉向。", "u": "b1c6.html#terms"}, {"k": "關鍵詞・臺灣史", "t": "國家語言", "c": "2019 年《國家語言發展法》確立，臺灣各固有族群使用的自然語言及臺灣手語皆為國家語言。", "u": "b1c6.html#terms"}, {"k": "年代・1627", "t": "荷蘭牧師甘治士來臺傳教", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1636", "t": "荷蘭人在新港社設學校，以羅馬字拼寫西拉雅語", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1666", "t": "臺南孔廟落成，稱全臺首學", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1685", "t": "沈光文與季麒光等人組東吟社，臺灣第一個詩社", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1788", "t": "乾隆賜客家義民「褒忠」匾額", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1859", "t": "天主教道明會郭德剛神父來臺，在打狗傳教", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1865", "t": "英國長老教會馬雅各抵臺南，以醫療傳教", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1872", "t": "加拿大長老教會馬偕抵淡水", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1885", "t": "巴克禮創辦《臺灣府城教會報》", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1901", "t": "臺灣神社落成", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1920", "t": "黃土水入選日本帝展，首位獲此殊榮的臺灣人", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1924", "t": "張我軍引發新舊文學論戰", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1926", "t": "賴和發表〈一桿「稱仔」〉；陳澄波以油畫入選帝展", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1927", "t": "第一回臺灣美術展覽會舉行，出現「臺展三少年」", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1930", "t": "黃石輝提倡鄉土文學，引發臺灣話文論戰", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1934", "t": "臺灣文藝聯盟成立，發行《臺灣文藝》", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1936以後", "t": "皇民化運動推行，寺廟整理與正廳改善展開", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1977-1978", "t": "鄉土文學論戰", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・1989", "t": "《悲情城市》獲威尼斯影展金獅獎", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "年代・2019", "t": "《國家語言發展法》公布，確立各族群語言的地位", "c": "臺灣史　宗教發展與藝文活動", "u": "b1c6.html#timeline"}, {"k": "中國與東亞史　緒論／導論", "t": "東亞：一個被歷史連起來的區域", "c": "緒論要替整冊建立兩個基本工具。第一個是「東亞」這個區域概念：它不是自然存在的地理單位，而是因為漢字、儒學、律令與佛教長期流通，才被歷史學者辨認出來的一個研究範圍。第二個是維繫這個區域的政治語言——朝貢與冊封。它在名義上是不平等的上下關係，實際運作卻同時包含貿易、外交承認與文化交流，各方也都懂得如何為自己的利益使用它。本節最後說明為什麼課綱要把「中國史」放進「東亞史」的脈絡來讀，並提醒：在這片區域裡，連一場戰爭、一個地名的稱呼方式，往往就藏著不同國家的立場。", "u": "b2c0.html"}, {"k": "中國與東亞史　0-1", "t": "「東亞」是怎麼被劃出來的", "c": "地理上的東亞與歷史上的東亞；「東亞世界」的四項共同要素；為什麼要把中國史放進東亞史", "u": "b2c0.html#s01"}, {"k": "中國與東亞史　0-2", "t": "朝貢與冊封：一套秩序的兩面", "c": "這套制度怎麼運作；不只是外交：朝貢的多重功能；這套秩序的限度", "u": "b2c0.html#s02"}, {"k": "中國與東亞史　0-3", "t": "漢字文化圈", "c": "共同的書寫工具；各地如何長出自己的文字；儒學、律令與佛教的傳布", "u": "b2c0.html#s03"}, {"k": "中國與東亞史　0-4", "t": "讀東亞史的幾個提醒", "c": "多中心的視角；名稱就是立場；本冊的六章地圖", "u": "b2c0.html#s04"}, {"k": "關鍵詞・中國與東亞史", "t": "東亞", "c": "地理上多指中國、朝鮮半島、日本列島與越南；作為歷史概念，指一群長期共享漢字、儒學、律令與佛教的社會。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "東亞世界論", "c": "日本學者西嶋定生提出的分析架構，以漢字、儒家思想、律令制度、漢傳佛教四項要素辨認歷史上的東亞。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "朝貢", "c": "周邊政權遣使獻上方物、奉表稱臣的儀式性往來，中國王朝則給予回賜。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "冊封", "c": "中國皇帝授予周邊統治者王號、官爵與印信，承認其統治的正當性。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "厚往薄來", "c": "中國回賜的價值通常高於貢品，以展現天朝氣度，也使朝貢帶有實質的貿易利益。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "勘合", "c": "明朝發給朝貢國的憑證，來船須持勘合比對相符才准入貢，用以管制貿易與辨別真偽。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "華夷秩序", "c": "以中國為中心、依親疏遠近排列周邊政權的世界觀，是一套說法而非固定事實。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "小中華", "c": "朝鮮、日本、越南等地自認保存中華文化正統的主張，顯示「中華」是可被挪用的文化資本。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "漢字文化圈", "c": "歷史上以漢字書寫、共享儒家經典與律令傳統的區域。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "漢文", "c": "以漢字書寫的古典書面語，長期作為東亞各地的官方與知識語言，與各地口語並不相同。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "筆談", "c": "語言不通的東亞知識分子以漢字書寫交談的方式，是近代以前重要的跨國溝通手段。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "《訓民正音》", "c": "1446 年朝鮮世宗頒布的表音文字，使一般人得以書寫，但士大夫長期仍以漢文為正式文體。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "喃字", "c": "越南人利用漢字部件創造、用以記錄越南語的文字，與漢文並行使用。", "u": "b2c0.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "條約體制", "c": "十九世紀由西方引入、以主權國家與條約為基礎的國際秩序，逐步取代朝貢體制。", "u": "b2c0.html#terms"}, {"k": "年代・前 108", "t": "漢武帝滅衛氏朝鮮設郡，漢字與典章制度大量進入朝鮮半島", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・3 世紀前期", "t": "倭女王卑彌呼遣使至魏，獲封「親魏倭王」", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・372", "t": "前秦遣僧送佛像經文至高句麗，佛教傳入朝鮮半島", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・6 世紀中葉", "t": "佛教經百濟傳入日本", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・607", "t": "日本遣小野妹子出使隋朝，國書措辭引起隋帝不悅", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・630", "t": "日本首次派出遣唐使", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・676", "t": "新羅大致統一朝鮮半島，與唐維持密切往來", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・701", "t": "日本頒行《大寶律令》，律令國家成形", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・894", "t": "日本停派遣唐使，本土文化色彩轉濃", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・939", "t": "吳權擊敗南漢，越南脫離中國直接統治", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・958", "t": "高麗光宗仿中國制度引進科舉", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・15 世紀初", "t": "足利義滿遣使明朝並受冊封，明日之間開始勘合貿易", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1446", "t": "朝鮮世宗頒布《訓民正音》", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1592–1598", "t": "豐臣秀吉出兵朝鮮，明朝派兵援助，東亞三方捲入大戰", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1637", "t": "朝鮮在清軍武力壓迫下改向清朝朝貢", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1842", "t": "《南京條約》簽訂，以條約為基礎的新秩序開始進入東亞", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1876", "t": "《江華條約》簽訂，日本以西式條約打開朝鮮門戶", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "年代・1895", "t": "《馬關條約》規定清朝承認朝鮮獨立，傳統朝貢秩序告終", "c": "中國與東亞史　東亞：一個被歷史連起來的區域", "u": "b2c0.html#timeline"}, {"k": "中國與東亞史　第 1 章", "t": "國家的統治", "c": "本章處理東亞國家治理技術的長期演變。西周以血緣為基礎的封建與宗法，在春秋戰國逐漸瓦解，秦統一後改行郡縣，並創立皇帝制度，把權力集中到單一頂點。此後兩千年的核心問題，是皇帝如何透過一套龐大的官僚體系管理疆域，而選官辦法從察舉、九品官人法一路走到科舉，決定了誰能進入這個體系。唐代成熟的律令格式成為東亞共同的制度範本，日本、朝鮮與越南各自取用改造，卻因社會結構不同而長出不同結果。十九世紀以後，帝制官僚在西力衝擊下被迫重組，1905 年廢科舉象徵一個延續千年的制度時代結束。", "u": "b2c1.html"}, {"k": "中國與東亞史　1-1", "t": "從封建到郡縣", "c": "西周的封建與宗法；封建秩序為什麼鬆動；秦：郡縣制與皇帝制度；漢初的折衷與修正", "u": "b2c1.html#s11"}, {"k": "中國與東亞史　1-2", "t": "皇帝制度與官僚體系", "c": "皇帝：一個新的權力位置；從三公九卿到三省六部；皇權與相權的長期拉鋸；中央如何管住地方", "u": "b2c1.html#s12"}, {"k": "中國與東亞史　1-3", "t": "選官制度的三次轉折", "c": "漢代的察舉與徵辟；九品官人法與門第社會；科舉的成形與成熟；科舉社會的兩面", "u": "b2c1.html#s13"}, {"k": "中國與東亞史　1-4", "t": "律令體制與東亞各國的取捨", "c": "律令格式：一套可以輸出的國家藍圖；日本：律令國家與它的變形；朝鮮：把科舉做到極致的社會；越南：長期郡縣經驗下的制度延續", "u": "b2c1.html#s14"}, {"k": "中國與東亞史　1-5", "t": "近代以後的變局", "c": "帝制官僚體系的瓦解；明治日本：另一種中央集權；朝鮮與越南的制度斷裂", "u": "b2c1.html#s15"}, {"k": "關鍵詞・中國與東亞史", "t": "宗法", "c": "以嫡長子繼承為核心的家族繼承制度，是西周封建的血緣基礎，分大宗與小宗。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "郡縣制", "c": "地方設郡、縣，長官由中央任免、領俸祿、可調動且不世襲，是中央集權的基本工具。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "皇帝制度", "c": "秦始皇創立，集最終決定權於一人，並以年號、禮儀與曆法不斷確認其特殊地位。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "推恩令", "c": "漢武帝的削藩辦法：令諸侯王把封地分給所有子弟，使王國自然變小。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "三省六部", "c": "隋唐中央官制，中書草擬、門下審議、尚書執行，尚書省下設吏戶禮兵刑工六部。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "內朝", "c": "皇帝以身邊近臣處理機要，用以分割外朝宰相權力的做法。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "通判", "c": "宋代設於各州、與知州共同署名文書的官員，作用是替中央監督地方。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "行省", "c": "元代中書省的派出機構，後固定為地方最高行政區，「省」的名稱沿用至今。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "軍機處", "c": "清雍正年間設立，軍機大臣承旨辦事，使決策集中且快速。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "察舉", "c": "漢代由地方長官推薦人才的選官辦法，科目有孝廉、賢良方正等，重德行名聲。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "九品官人法", "c": "魏晉選官制度，由中正官依家世品行評定九等；實際運作導致門第壟斷仕途。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "糊名與謄錄", "c": "宋代科舉的防弊措施：遮住考生姓名並另抄試卷，避免考官辨識筆跡或關說。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "律令格式", "c": "唐代法制的四種形式：律為刑法、令為制度規定、格為補充修正、式為施行細則。", "u": "b2c1.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "兩班", "c": "朝鮮王朝的統治身分階層，原指文武官員，後固化為世襲集團，科舉大致限於此一階層。", "u": "b2c1.html#terms"}, {"k": "年代・約前 11 世紀", "t": "周滅商，行封建以藩屏周室", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 770", "t": "周室東遷，封建秩序逐漸鬆動", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 356 起", "t": "商鞅在秦推行變法，獎勵耕戰、普遍設縣", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 221", "t": "秦統一六國，創皇帝制度、全面推行郡縣", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 154", "t": "吳楚七國之亂，郡國並行的矛盾爆發", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 134", "t": "漢武帝令郡國舉孝廉，察舉制度確立", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・前 127", "t": "漢武帝行推恩令，逐步削弱諸侯王", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・220", "t": "魏行九品官人法，門第逐漸壟斷仕途", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・587", "t": "隋文帝令各州歲貢士人，改以考試選才", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・605 前後", "t": "隋煬帝設進士科，科舉制度成形", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・604", "t": "日本頒布十七條憲法，吸收中國政治理念", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・645", "t": "日本大化革新，推動公地公民與中央集權", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・653", "t": "唐頒《永徽律疏》，成為東亞律令的重要範本", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・701", "t": "日本頒行《大寶律令》，律令國家成形", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・958", "t": "高麗光宗引進科舉", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・973", "t": "宋太祖首開殿試，及第者成為「天子門生」", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・1075", "t": "越南李朝首次開科取士", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・1380", "t": "明太祖廢丞相，六部直屬皇帝", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・雍正年間", "t": "清設軍機處，決策效率提高、皇權更加集中", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "年代・1894／1905", "t": "朝鮮甲午更張廢科舉；清廷下詔停止科舉", "c": "中國與東亞史　國家的統治", "u": "b2c1.html#timeline"}, {"k": "中國與東亞史　第 2 章", "t": "社會組織", "c": "本章處理國家之外的社會如何自我組織。從西周宗法到明清宗族，父系家族始終是最基本的單位，但它的形式其實被反覆重建：宋代以後出現族田、祠堂、族譜與家訓，宗族才成為普及的庶民組織。社會上層則歷經從門第世族到科舉士人的替換，取得功名的士紳成為官府與百姓之間的關鍵中介。城市方面，唐宋之際坊市制度崩解，商業空間與市民娛樂大幅擴張，明清更出現大量專業市鎮與商幫組織。在基層，國家以里甲、保甲進行控制，地方則以鄉約進行自律，兩者互相補充也互相角力。最後從家庭與女性的處境出發，比較中國、日本、朝鮮與越南的差異，說明「儒家社會」並非一個模子刻出來的。", "u": "b2c2.html"}, {"k": "中國與東亞史　2-1", "t": "宗族：一個被反覆重建的組織", "c": "從宗法到家族；宋代以後的新宗族；宗族在地方社會的實際功能；宗族並非各地一致", "u": "b2c2.html#s21"}, {"k": "中國與東亞史　2-2", "t": "從門第到士紳：社會上層的替換", "c": "門第社會的形成與崩解；科舉社會與士大夫；士紳：官府與百姓之間的中介", "u": "b2c2.html#s22"}, {"k": "中國與東亞史　2-3", "t": "城市、市鎮與商人組織", "c": "唐宋之際的城市革命；明清的市鎮與區域分工；行會、商幫與會館；市民生活與社會風氣", "u": "b2c2.html#s23"}, {"k": "中國與東亞史　2-4", "t": "鄉里控制與地方自律", "c": "國家的基層編組；鄉約：社會的自我約束；村落、水利與信仰組織", "u": "b2c2.html#s24"}, {"k": "中國與東亞史　2-5", "t": "家庭、女性與東亞社會的比較", "c": "婚姻與家庭的規範；女性的處境：不只有一種樣貌；日本與朝鮮：兩種不同的家；越南與比較的意義", "u": "b2c2.html#s25"}, {"k": "關鍵詞・中國與東亞史", "t": "宗族", "c": "奉同一始祖、跨越許多戶的父系親屬組織，典型配備為族譜、祠堂、族田與家訓。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "義莊", "c": "以族田收入贍養族人、支助應考與婚喪的家族公產，范仲淹所設的范氏義莊為著名先例。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "族譜", "c": "記錄世系與族規的文獻；既是親屬名冊，也是宗族宣示身分與正統的工具。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "門第", "c": "魏晉南北朝以家世高低決定仕途與婚姻的社會結構，重視郡望與譜牒。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "士大夫", "c": "宋代以後憑功名與學問取得地位的統治階層，取代了憑血統的世族。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "士紳", "c": "明清取得生員以上功名者，享有免役等特權，是官府與百姓之間的地方中介。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "坊市制", "c": "唐代住宅區與商業區分離、市有定時並實施宵禁的城市管理制度，宋代以後瓦解。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "瓦舍勾欄", "c": "宋代城市中的娛樂場所，有說書、雜劇與各類表演，是市民文化的集中地。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "市鎮", "c": "明清縣城以下因產業或交易而興起的聚落，如景德鎮、佛山鎮，常比縣城更繁榮。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "會館與公所", "c": "商人依同鄉或同業組成的組織，提供住宿、議事、祭祀、互助與糾紛調解。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "里甲制", "c": "明代以一百一十戶為一里、十戶輪任里長的基層編組，用以催徵賦役與管理戶口。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "保甲", "c": "以戶為單位層層編組、懸掛門牌並實施連坐的治安制度，宋代已見，清代普遍施行。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "鄉約", "c": "鄉里人自願參加的自律公約，以德業相勸、過失相規、禮俗相交、患難相恤為原則。", "u": "b2c2.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "七出三不去", "c": "傳統法禮中丈夫休妻的七項理由，以及三種不得休妻的限制情形。", "u": "b2c2.html#terms"}, {"k": "年代・前 11 世紀", "t": "西周行宗法封建，確立嫡長子繼承原則", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・東漢", "t": "累世經學的豪族興起，與察舉制度互相結合", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・220 以後", "t": "九品官人法施行，門第社會逐漸形成", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・唐末五代", "t": "長期戰亂摧毀世族莊園與譜牒，門第社會瓦解", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1049", "t": "范仲淹設置范氏義莊，以族田贍養族人", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1070", "t": "王安石推行保甲法，編組民戶輪值巡警", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・北宋", "t": "坊市制度瓦解，夜市與瓦舍勾欄興盛", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・北宋", "t": "藍田呂氏訂立鄉約，提出德業相勸等四項原則", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・南宋", "t": "《家禮》流傳，冠婚喪祭儀節簡化並向庶民普及", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1381", "t": "明編賦役黃冊，確立里甲制度", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・明代中期", "t": "朝廷放寬民間祭祀始祖，華南祠堂大量興建", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1588 前後", "t": "豐臣秀吉推行刀狩，日本走向兵農分離", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・明清", "t": "江南市鎮與晉商、徽商等商幫興盛，會館公所遍布各地", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・清初", "t": "推行保甲與門牌，強化基層稽查與連坐", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・朝鮮後期", "t": "父系化加強，祭祀集中於長子，族譜編纂大盛", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・清中葉以後", "t": "士紳辦團練、組鄉勇，地方軍事與財政角色大增", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1905", "t": "廢科舉，士紳的功名來源消失，地方社會結構開始改變", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "年代・1911 以後", "t": "新式學堂、報刊與商會興起，傳統社會組織逐步轉型", "c": "中國與東亞史　社會組織", "u": "b2c2.html#timeline"}, {"k": "中國與東亞史　第 3 章", "t": "近代以前中國人群移動與交流", "c": "本章處理近代以前東亞內部的人群移動。陸上方面，北方民族南下與漢人南遷交替發生，既造成戰亂與流離，也帶來人口、技術與文化的重新分布，南方因此逐步成為經濟重心。草原與綠洲構成的陸上通道，讓絲綢、馬匹、宗教與疾病一同流通；海上則發展出從東海到南海、再連上印度洋的貿易網，唐宋設市舶司管理，明初鄭和下西洋把官方主導的航海推到極致。明清雖然實行海禁，民間海商與下南洋的移民仍持續活動，並在十六世紀以後與美洲、日本的白銀連成一個全球性的交換體系。", "u": "b2c3.html"}, {"k": "中國與東亞史　3-1", "t": "北方民族南下與漢人南遷", "c": "三波大規模的南遷；北方民族的入主與統治設計；元朝的族群分類問題；移動帶來的長期影響", "u": "b2c3.html#s31"}, {"k": "中國與東亞史　3-2", "t": "陸上通道：草原與綠洲", "c": "絲路的開通與運作；流通的不只是絲綢；蒙古帝國時期的歐亞通道", "u": "b2c3.html#s32"}, {"k": "中國與東亞史　3-3", "t": "海洋的東亞：港口、市舶與鄭和", "c": "季風、船與航線；市舶制度與海上貿易的管理；鄭和下西洋；琉球與東海的中介者", "u": "b2c3.html#s33"}, {"k": "中國與東亞史　3-4", "t": "海禁、海商與下南洋", "c": "明清的海禁政策；倭寇與民間海上勢力；華人向東南亞移動；移動與作物、技術的傳播", "u": "b2c3.html#s34"}, {"k": "中國與東亞史　3-5", "t": "白銀時代：十六至十八世紀的東亞", "c": "白銀為什麼流向中國；日本的對外窗口；一個區域性的交換體系", "u": "b2c3.html#s35"}, {"k": "關鍵詞・中國與東亞史", "t": "衣冠南渡", "c": "西晉末年北方士族與百姓因戰亂南遷的現象，是經濟重心南移的重要開端。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "南北面官制", "c": "遼的統治設計：北面官依契丹舊制治游牧部族，南面官依漢制治農耕人口。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "猛安謀克", "c": "金在女真本族推行的編組，兼具軍事單位與生產單位的性質。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "市舶司", "c": "宋代管理海外貿易的機構，負責查驗船貨、抽稅、博買與發給公憑。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "蕃坊", "c": "唐宋廣州、泉州等港口供外商聚居的區域，設蕃長協助管理。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "水密隔艙", "c": "把船艙分隔成互不相通的空間，一處破損不致全船進水的造船技術。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "鄭和下西洋", "c": "1405–1433 年明朝官方主導的七次遠洋航行，重在宣揚國威與擴大朝貢關係。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "海禁", "c": "限制民間私自出海貿易的政策，明清時期時緊時鬆，並非完全斷絕對外往來。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "隆慶開關", "c": "1567 年前後明朝在福建月港部分開放民間出海，海外貿易取得有限的合法空間。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "遷界令", "c": "清初為斷絕沿海居民對鄭氏政權的接濟，強迫沿海居民內遷的政策。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "公行", "c": "清代廣州負責與外商交易並代辦稅務的商人組織，是一口通商時期的關鍵中介。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "一條鞭法", "c": "明代把各項賦役合併折收銀兩的稅制改革，使白銀成為國家財政核心。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "馬尼拉大帆船", "c": "往來馬尼拉與美洲的貿易船，將美洲白銀運至亞洲、換取中國商品。", "u": "b2c3.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "蘭學", "c": "日本經由長崎輸入荷蘭書籍而發展出的西方知識研究，涵蓋醫學、天文與地理。", "u": "b2c3.html#terms"}, {"k": "年代・前 138／前 119", "t": "張騫兩度出使西域，打開對中亞的認識", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・前 60", "t": "西漢設西域都護府，陸上通道趨於穩定", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・311–317", "t": "永嘉之亂與衣冠南渡，第一波大規模南遷", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・494", "t": "北魏孝文帝遷都洛陽，推動漢化政策", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・714 前後", "t": "唐設市舶使於廣州，管理海外貿易", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・755–763", "t": "安史之亂，人口與財富持續南移", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1126–1127", "t": "靖康之變，宋室南遷，江南再度躍升", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・13 世紀", "t": "蒙古擴張與驛站系統使歐亞交通空前便利", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・元代", "t": "泉州成為東亞重要國際港，多種宗教遺跡並存", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1405–1433", "t": "鄭和七下西洋，航跡遠達東非與阿拉伯半島", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・15 世紀", "t": "琉球王國活躍於東亞轉口貿易", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1565 起", "t": "馬尼拉大帆船貿易展開，美洲白銀經太平洋流入亞洲", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1567 前後", "t": "隆慶開關，福建月港部分開放民間出海", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1581 前後", "t": "一條鞭法推行全國，賦役折銀", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・17 世紀初", "t": "德川幕府發給朱印狀，朱印船往來東南亞", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1639–1641", "t": "日本大幅限制對外往來，僅留長崎、對馬、薩摩、松前四個窗口", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1661–1683", "t": "清初遷界令強迫沿海居民內遷", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1684", "t": "清廷開海貿易，隨後設閩粵江浙四處海關", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1740", "t": "巴達維亞發生大規模殺害華人事件", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "年代・1757", "t": "清限定歐洲貿易於廣州一口，由公行居間經理", "c": "中國與東亞史　近代以前中國人群移動與交流", "u": "b2c3.html#timeline"}, {"k": "中國與東亞史　第 4 章", "t": "近代以後東亞人群移動與交流", "c": "本章處理十九世紀以後東亞人群移動的規模與性質變化。條約港的開設創造了新的移動節點，輪船、電報與資本把沿海地區接進世界市場，也把人口推上遠洋航線。苦力貿易與海外華工代表移動中最不自由的一端，勞動條件惡劣、受騙與死亡率高，並在移入國引發排華立法。另一方面，僑匯、僑批與僑鄉建築說明移民與家鄉始終緊密相連。日本帝國擴張期間，官方政策直接牽動臺灣、朝鮮、中國東北與日本本土之間的人口流向，戰時動員更使強制勞動成為爭議至今的問題。戰後的遣返、遷臺、難民與冷戰分斷重塑了區域人口，1980 年代以後則進入以移工、婚姻移民與跨國工作為主的新階段。", "u": "b2c4.html"}, {"k": "中國與東亞史　4-1", "t": "條約港：新的移動節點", "c": "從一口通商到條約體制；條約港的城市與人；輪船、電報與移動成本的下降；移動的推力與拉力", "u": "b2c4.html#s41"}, {"k": "中國與東亞史　4-2", "t": "苦力貿易與海外華工", "c": "契約華工制度；國際輿論與制度的調整；北美與大洋洲的華工與排華；第一次世界大戰的華工", "u": "b2c4.html#s42"}, {"k": "中國與東亞史　4-3", "t": "僑鄉、僑匯與僑民社會", "c": "僑鄉的形成；海外華人社會的組織；僑民與近代中國的政治", "u": "b2c4.html#s43"}, {"k": "中國與東亞史　4-4", "t": "日本帝國下的人群移動", "c": "殖民統治與官方主導的移動；被殖民者的移動；戰時動員與強制勞動；日本人的海外移民", "u": "b2c4.html#s44"}, {"k": "中國與東亞史　4-5", "t": "戰後到當代的移動", "c": "戰爭結束後的大規模人口重組；冷戰分斷下的離散；經濟起飛與新的移動方向；當代臺灣與東亞的跨國移動", "u": "b2c4.html#s45"}, {"k": "關鍵詞・中國與東亞史", "t": "條約港", "c": "依不平等條約開放外人通商居住的口岸，同時是貨物、資本與人員流動的節點。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "買辦", "c": "受僱於外商、熟悉語言與地方商情的中國商人，是外資進入中國市場的中介。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "契約華工", "c": "簽訂數年期勞動契約出洋工作的華人勞工，俗稱賣豬仔，實際自由常受嚴重限制。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "苦力貿易", "c": "十九世紀中期以招募契約勞工為名的跨洋人口運送，欺騙與高死亡率為其特徵。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "排華法案", "c": "美國於 1882 年通過、限制華工入境的法律，是以法律形式落實種族歧視的代表。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "以工代兵", "c": "第一次世界大戰期間中國以派遣勞工參與協約國，期望戰後取得發言權的策略。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "僑鄉", "c": "因長期大量移民海外而形成的原鄉地區，經濟與社會高度依賴僑匯。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "僑批", "c": "閩粵地區附有匯款的家書，由專門批局遞送，形成跨國的通訊與信用網絡。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "華僑與華人", "c": "前者指仍具母國國籍的旅外者，後者多指已取得所在國國籍的族裔群體。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "開拓團", "c": "1932 年後日本組織前往中國東北從事農業移民的團體，由國策公司主導。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "引揚", "c": "第二次世界大戰結束後，海外日本軍民被遣返回國的過程。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "離散家族", "c": "因戰爭或分斷而被迫分隔兩地、長期無法團聚的家庭，朝鮮半島為典型案例。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "印度支那難民", "c": "1975 年以後自越南、寮國與柬埔寨外逃的難民，多經海路離境。", "u": "b2c4.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "移工", "c": "以工作為目的短期居留他國的勞動者；在臺灣主要來自印尼、越南、菲律賓與泰國。", "u": "b2c4.html#terms"}, {"k": "年代・1842", "t": "《南京條約》開五口通商，條約體制開始運作", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1845", "t": "上海劃設租界，形成華洋雜處的複合城市", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1848 起", "t": "加州發現金礦，華人大量前往北美", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1860", "t": "《北京條約》明文允許華工出洋", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1860–1870 年代", "t": "契約華工大量輸往古巴、祕魯，苦力貿易達到高峰", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1870 年代", "t": "清廷派員赴古巴調查華工處境；澳門停止苦力出口", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1882", "t": "美國通過排華法案，限制華工入境", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1895", "t": "臺灣成為日本殖民地，日本人開始移入", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1908", "t": "首批日本移民搭船抵達巴西", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1910", "t": "日本併吞大韓帝國，朝鮮人移動方向大幅改變", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1916 起", "t": "英法在中國招募華工赴歐，人數達十餘萬", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1932", "t": "滿洲國成立，日本推動向中國東北的農業移民", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1939 以後", "t": "日本戰時動員大量朝鮮人與中國人從事勞動", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1945–1946", "t": "日本軍民自海外陸續遣返，稱為引揚", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1945–1950 年代", "t": "約一百餘萬軍公教人員與眷屬自中國大陸遷臺", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1950–1953", "t": "韓戰造成朝鮮半島分斷與長期的離散家族問題", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1975 以後", "t": "越戰結束，印度支那難民大量外逃", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1989", "t": "臺灣因重大工程專案首度引進外籍勞工", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1992", "t": "《就業服務法》公布施行，外籍移工制度化", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "年代・1990 年代以後", "t": "跨國婚姻增加，新住民成為臺灣社會的重要組成", "c": "中國與東亞史　近代以後東亞人群移動與交流", "u": "b2c4.html#timeline"}, {"k": "中國與東亞史　第 5 章", "t": "傳統與現代的交會", "c": "本章處理十九世紀以後東亞面對西力衝擊的回應。清朝先以自強運動引進船砲與機器，但改革侷限於器物層次、缺乏統一規劃與制度配套；日本則在明治維新中同時改造政治、軍事、財政、教育與社會身分，建立起能直接動員全國的近代國家。甲午戰敗暴露了兩種路徑的落差，此後中國依序經歷戊戌變法、義和團與八國聯軍、清末新政與辛亥革命，改革的深度不斷加大，政治秩序卻也持續動盪。新文化運動把檢討推向語言與思想層面，五四則把知識分子的主張與群眾運動結合起來。本章最後比較東亞各國不同的現代化路徑，並說明現代化從來不是單純的進步，而是伴隨代價與爭論的複雜過程。", "u": "b2c5.html"}, {"k": "中國與東亞史　5-1", "t": "西力衝擊與條約體制", "c": "衝擊從哪裡來；條約體制取代朝貢體制；衝擊如何擴散到鄰國", "u": "b2c5.html#s51"}, {"k": "中國與東亞史　5-2", "t": "自強運動：從器物開始的改革", "c": "推動者與基本主張；具體的建設；為什麼成效有限；甲午戰爭的檢驗", "u": "b2c5.html#s52"}, {"k": "中國與東亞史　5-3", "t": "明治維新：一場全面的體制改造", "c": "從開港到倒幕；拆掉舊體制；建立新體制；與自強運動的對照", "u": "b2c5.html#s53"}, {"k": "中國與東亞史　5-4", "t": "從戊戌變法到辛亥革命", "c": "戊戌變法；義和團與辛丑和約；清末新政與立憲運動；辛亥革命", "u": "b2c5.html#s54"}, {"k": "中國與東亞史　5-5", "t": "新文化、五四與現代化的多條路徑", "c": "新文化運動；五四運動；東亞現代化路徑的比較；戰後中國：計畫經濟到改革開放", "u": "b2c5.html#s55"}, {"k": "關鍵詞・中國與東亞史", "t": "領事裁判權", "c": "外國人在中國犯案時由其本國領事依本國法律審判，中國司法權因此受限。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "協定關稅", "c": "稅率須與外國協商訂定，使中國失去自主調整關稅的能力。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "片面最惠國待遇", "c": "一國取得的權益自動適用於其他締約國，使讓步不斷擴散且無法收回。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "總理各國事務衙門", "c": "1861 年清廷設立、以近代外交方式處理對外事務的機構。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "中學為體，西學為用", "c": "主張保留既有制度與倫理、只引進西方技術的改革思路，是自強運動的核心邏輯。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "官督商辦", "c": "由官方監督、商人集資經營的企業形式，易受官員干預而難依商業原則運作。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "廢藩置縣", "c": "1871 年日本取消藩、改設府縣，把地方權力收歸中央的關鍵改革。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "地租改正", "c": "1873 年日本改以土地價格按固定比率徵收現金地租，使國家財政穩定可預測。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "岩倉使節團", "c": "1871–1873 年日本派往歐美的大型考察團，成員回國後主導多項制度設計。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "百日維新", "c": "1898 年戊戌變法的別稱，推行約百日即被終止。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "預備立憲", "c": "清末宣示將逐步實施憲政的政策，包括頒布憲法大綱、設諮議局與資政院。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "三民主義", "c": "孫文提出的民族、民權、民生三項主張，是同盟會與其後革命的綱領。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "新文化運動", "c": "1910 年代中期起以民主與科學為號召、主張白話文與思想解放的文化運動。", "u": "b2c5.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "改革開放", "c": "1978 年底中共確立的政策方向，逐步引進市場機制、設立經濟特區並吸引外資。", "u": "b2c5.html#terms"}, {"k": "年代・1840–1842", "t": "鴉片戰爭與《南京條約》，條約體制開始", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1853–1854", "t": "美國艦隊駛入日本，隔年簽訂和親條約", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1856–1860", "t": "英法聯軍，簽訂《天津條約》《北京條約》", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1861", "t": "清設總理各國事務衙門，自強運動展開", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1865–1866", "t": "江南製造局、福州船政局先後設立", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1867–1868", "t": "日本大政奉還，明治新政府成立", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1871", "t": "日本廢藩置縣；岩倉使節團出發赴歐美考察", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1873", "t": "日本實施地租改正與徵兵令", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1876", "t": "《江華條約》簽訂，朝鮮被迫開港", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1884–1885", "t": "中法戰爭，清朝放棄對越南的宗主權", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1888", "t": "北洋海軍正式成軍", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1889–1890", "t": "日本頒布憲法並開設議會", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1894–1895", "t": "甲午戰爭與《馬關條約》", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1898", "t": "戊戌變法推行約百日後失敗", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1900–1901", "t": "八國聯軍入北京，簽訂《辛丑和約》", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1901 起", "t": "清末新政展開；1905 年停止科舉", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1911", "t": "武昌起義，各省響應", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1912", "t": "中華民國成立，清帝退位", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1915–1919", "t": "新文化運動展開，1919 年爆發五四運動", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "年代・1978 以後", "t": "中國大陸推動改革開放，1980 年設立經濟特區", "c": "中國與東亞史　傳統與現代的交會", "u": "b2c5.html#timeline"}, {"k": "中國與東亞史　第 6 章", "t": "戰爭與和平", "c": "本章處理東亞的戰爭與戰後的和解問題。傳統時代的朝貢秩序雖以德化為理想，實際上仍有大規模的軍事衝突，十六世紀末的朝鮮戰場就同時捲入中、朝、日三方。近代以後，甲午戰爭與日俄戰爭重組了東亞的權力格局，日本取代清朝成為區域強權，朝鮮則失去獨立。1930 年代起中日之間的衝突擴大為全面戰爭，並在 1941 年後併入第二次世界大戰。戰後的處置包括東京審判、各項和約與領土安排，但許多問題並未真正解決。冷戰又把區域切割成對立陣營，韓戰與越戰留下至今未癒的分斷。最後本章討論歷史記憶：面對教科書、參拜、賠償與受害者權益等爭議，重點不在替誰下結論，而在理解各方為什麼會那樣主張。", "u": "b2c6.html"}, {"k": "中國與東亞史　6-1", "t": "傳統東亞的戰爭與秩序", "c": "朝貢秩序下的戰爭觀；十六世紀末的朝鮮戰場；清朝的邊疆與東亞格局", "u": "b2c6.html#s61"}, {"k": "中國與東亞史　6-2", "t": "甲午、日俄與東亞秩序的重組", "c": "甲午戰爭；日俄戰爭；第一次世界大戰前後的東亞；一九三零年代的緊張升高", "u": "b2c6.html#s62"}, {"k": "中國與東亞史　6-3", "t": "中日戰爭與太平洋戰爭", "c": "全面戰爭的爆發；南京事件與戰爭中的平民；太平洋戰爭與同盟國陣營；戰爭的代價", "u": "b2c6.html#s63"}, {"k": "中國與東亞史　6-4", "t": "戰後處置與東京審判", "c": "遠東國際軍事法庭；和約與領土安排；賠償與後續交涉", "u": "b2c6.html#s64"}, {"k": "中國與東亞史　6-5", "t": "冷戰下的東亞與歷史記憶", "c": "韓戰與朝鮮半島的分斷；越戰與冷戰前線；歷史記憶為何成為現實問題；道歉、賠償與和解的嘗試", "u": "b2c6.html#s65"}, {"k": "關鍵詞・中國與東亞史", "t": "壬辰倭亂", "c": "1592–1598 年日本出兵朝鮮的戰爭；中國稱萬曆朝鮮之役，日本稱文祿、慶長之役。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "《馬關條約》", "c": "1895 年甲午戰後簽訂，清朝承認朝鮮獨立、割讓臺澎、賠款並開放日本設廠。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "三國干涉還遼", "c": "1895 年俄德法三國要求日本歸還遼東半島，清朝另付贖遼費用。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "二十一條", "c": "1915 年日本向中國政府提出的一系列要求，最終部分條款被迫接受。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "九一八事變", "c": "1931 年日軍在中國東北發動軍事行動，隔年扶植成立滿洲國。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "盧溝橋事變", "c": "1937 年 7 月 7 日的軍事衝突，中日由此進入全面戰爭。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "南京事件", "c": "1937 年 12 月日軍占領南京後對戰俘與平民的大規模殺害與暴行；遇難人數的估計各方差異很大。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "《開羅宣言》", "c": "1943 年開羅會議後發表，聲明日本應歸還其奪取的中國領土。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "《波茨坦宣言》", "c": "1945 年 7 月發布，要求日本投降並重申開羅宣言條款應被履行。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "遠東國際軍事法庭", "c": "1946–1948 年在東京審判日本戰爭領導階層的法庭，亦稱東京審判。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "《舊金山和約》", "c": "1951 年簽署、1952 年生效，日本放棄臺澎等權利但未載明移交對象。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "停戰協定", "c": "1953 年韓戰交戰方簽訂的協定；因未締結和平條約，法律上仍屬停戰狀態。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "歷史認識問題", "c": "各國對同一段戰爭史的事實認定、責任歸屬與紀念方式產生分歧，並影響現實外交。", "u": "b2c6.html#terms"}, {"k": "關鍵詞・中國與東亞史", "t": "共同歷史教材", "c": "由不同國家的學者合作編寫、並陳各方觀點的歷史讀本，是推動和解的嘗試之一。", "u": "b2c6.html#terms"}, {"k": "年代・1592–1598", "t": "豐臣秀吉出兵朝鮮，明朝派兵援助，三方均損失慘重", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1894–1895", "t": "甲午戰爭；《馬關條約》割讓臺灣澎湖，三國干涉還遼", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1904–1905", "t": "日俄戰爭，日本取得南滿權益；朝鮮成為日本保護國", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1910", "t": "日本併吞大韓帝國", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1915", "t": "日本向中國提出二十一條要求", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1919", "t": "巴黎和會山東問題引發五四運動", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1931", "t": "九一八事變，日本占領中國東北", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1932", "t": "滿洲國成立；國際聯盟派員調查", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1936", "t": "西安事變，國共關係轉變", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1937", "t": "盧溝橋事變，中日全面戰爭；12 月南京陷落", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1941", "t": "日本襲擊珍珠港，太平洋戰爭爆發", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1943", "t": "開羅會議發表宣言", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1945", "t": "廣島長崎原子彈；8 月 15 日日本宣布接受《波茨坦宣言》", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1946–1948", "t": "遠東國際軍事法庭（東京審判）開庭與判決", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1950–1953", "t": "韓戰；1953 年簽訂停戰協定，未簽和平條約", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1951／1952", "t": "《舊金山和約》簽署與生效；中華民國與日本另簽和約", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1954–1975", "t": "越南戰爭；1975 年結束，隔年越南統一", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1965", "t": "日本與大韓民國簽訂基本條約", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1972", "t": "日本與中華人民共和國發表聯合聲明建交；沖繩交還日本", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "年代・1993／1995", "t": "日本先後發表關於慰安婦問題與殖民統治、侵略的談話", "c": "中國與東亞史　戰爭與和平", "u": "b2c6.html#timeline"}, {"k": "世界史　第 1 章", "t": "古代文化與基督教傳統", "c": "本章處理歐洲文化的三大根源。古希臘從神話思維走向哲學思辨，在城邦生活中孕育民主與人文精神；羅馬承繼希臘文化，發展出法治與制衡的政治傳統；基督教則從被迫害的小教派，一路成為羅馬國教、中古西歐的社會支柱。最後的文藝復興，透過重新發掘古典，把關注焦點從「神」拉回「人」，成為近代歐洲的起點。", "u": "b3c1.html"}, {"k": "世界史　1-1", "t": "古代文化的遺產", "c": "希臘文明與神話思維；城邦生活與雅典民主；希臘哲學三階段；希臘化時代的轉向；羅馬：承繼者與立法者", "u": "b3c1.html#s11"}, {"k": "世界史　1-2", "t": "基督教世界的形成", "c": "從猶太一神信仰到基督教；從教難到國教；教會、教宗與修院；政教之間的拉鋸；東西教會分裂與中古遺產", "u": "b3c1.html#s12"}, {"k": "世界史　1-3", "t": "文藝復興", "c": "為什麼發生在義大利？；人文主義的核心；文學、藝術、建築；北方文藝復興與影響", "u": "b3c1.html#s13"}, {"k": "關鍵詞・世界史", "t": "城邦（Polis）", "c": "以市鎮為核心、包含周邊農村的希臘政治單位。公民參與公共事務，形成強烈認同。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "神人同形同性", "c": "希臘眾神在外貌與情感上與人相同，也不完全公正——人文思維的起點。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "辯士學派", "c": "以普羅塔哥拉斯為代表，教授論辯技巧、主張沒有絕對真理，帶有懷疑主義色彩。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "觀念論", "c": "柏拉圖主張物質世界之上存在永恆、客觀、完美的「觀念」世界。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "希臘化時代", "c": "323–30 B.C.，亞歷山大死後至羅馬征服托勒密王國，希臘文化與東方文化融合的時期。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "斯多噶學派", "c": "芝諾創立，主張以理性克制慾望、順應宇宙自然秩序；深刻影響羅馬法哲學。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "《十二表法》", "c": "羅馬最早的成文法，公告於廣場，保障平民權益。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "自然法", "c": "羅馬人認為人類世界存在理性公義的最高法則，是民法與萬民法的上位原則。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "《米蘭詔令》", "c": "313 年君士坦丁頒布，使基督教在羅馬帝國內合法化。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "三位一體", "c": "尼西亞會議確立：上帝以聖父、聖子、聖靈三種形式顯現，本質上同屬一位。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "丕平獻土", "c": "矮子丕平將義大利中部土地獻給教宗，成為日後教宗國的基礎。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "亞威農之囚", "c": "1309–1377 教廷遷至法國亞威農，教宗多由法籍樞機擔任，形同法國附庸。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "人文主義", "c": "以古典語言文獻研究為基礎、以人為中心的教育與學術運動，重視理性與現世成就。", "u": "b3c1.html#terms"}, {"k": "關鍵詞・世界史", "t": "基督教人文主義", "c": "北方文藝復興的產物，回到《聖經》原典追求真誠虔敬，成為宗教改革養分。", "u": "b3c1.html#terms"}, {"k": "年代・約 1600 B.C.", "t": "邁錫尼文明興起", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・約 900 B.C.", "t": "希臘出現城邦", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・509 B.C.", "t": "羅馬共和開始", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・499–449 B.C.", "t": "波希戰爭", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・431–404 B.C.", "t": "伯羅奔尼撒戰爭", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・323 B.C.", "t": "亞歷山大逝世，希臘化時代開始", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・27 B.C.", "t": "屋大維獲「奧古斯都」稱號，羅馬帝國開始", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・約 A.D. 30", "t": "耶穌受難", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・313", "t": "君士坦丁頒布《米蘭詔令》", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・380", "t": "狄奧多西一世宣布基督教為國教", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・476", "t": "西羅馬帝國滅亡", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・800", "t": "查理曼受教宗加冕", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1054", "t": "東西教會正式分裂", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1096–1291", "t": "十字軍運動", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1122", "t": "《沃姆斯協定》", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1309–1377", "t": "亞威農之囚", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1378–1417", "t": "教會大分裂", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・1453", "t": "拜占庭帝國滅亡", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "年代・約 1455", "t": "古騰堡改良活字印刷術", "c": "世界史　古代文化與基督教傳統", "u": "b3c1.html#timeline"}, {"k": "世界史　第 2 章", "t": "個人自由理性的追尋", "c": "本章追蹤「個人」如何一步步從教會與國王手中取回主導權。宗教改革打破教會的信仰壟斷，科學革命建立以觀察與數學為基礎的新知識觀，啟蒙運動則把理性推向政治，主張政府的權力來自人民同意。這股力量在英國光榮革命、美國獨立、法國大革命中具體落地，並在工業化後分裂成資本主義與社會主義兩條路線，最後在民族主義的推動下，促成義大利與德意志的統一。", "u": "b3c2.html"}, {"k": "世界史　2-1", "t": "從宗教改革到啟蒙運動", "c": "宗教改革的爆發；新教的分流與反宗教改革；科學革命；啟蒙運動", "u": "b3c2.html#s21"}, {"k": "世界史　2-2", "t": "歐美民主政治的形塑", "c": "英國：議會政治的確立；美國：獨立革命與聯邦憲法；法國大革命與拿破崙", "u": "b3c2.html#s22"}, {"k": "世界史　2-3", "t": "歐美政治經濟思潮的發展", "c": "工業革命與社會變遷；資本主義與自由主義；社會主義的挑戰；民族主義與義、德統一", "u": "b3c2.html#s23"}, {"k": "關鍵詞・世界史", "t": "因信得救", "c": "馬丁‧路德主張人得救完全依憑上帝恩典與個人信仰，不需教會中介。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "預選說", "c": "喀爾文主張人是否得救早由上帝決定，信徒應以勤奮節儉的現世生活榮耀上帝。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "反宗教改革", "c": "天主教會的自我整頓與反擊，包括特倫特大公會議與耶穌會的教育、傳教工作。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "《西發里亞和約》", "c": "1648 年結束三十年戰爭，確立各邦自主決定宗教，並奠定近代主權國家體系。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "科學革命", "c": "十六至十七世紀以觀察、實驗與數學建立自然法則的知識轉型，代表人物有哥白尼、伽利略、牛頓。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "自然權利", "c": "洛克主張人生而享有生命、自由與財產的權利，政府的正當性來自人民同意。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "三權分立", "c": "孟德斯鳩主張行政、立法、司法分立並相互制衡，以防權力集中。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "公意", "c": "盧梭《社會契約論》的概念，指全體人民共同的意志，是主權的來源。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "《大憲章》", "c": "1215 年英國貴族迫使國王簽署，限制王權，是憲政傳統的起點。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "光榮革命", "c": "1688 年英國以不流血方式更換君主，次年《權利法案》確立議會高於國王。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "看不見的手", "c": "亞當斯密的比喻：市場中個人追求自利，反而促成整體資源的有效配置。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "《共產黨宣言》", "c": "1848 年馬克思、恩格斯發表，主張階級鬥爭是歷史動力，號召無產階級革命。", "u": "b3c2.html#terms"}, {"k": "關鍵詞・世界史", "t": "鐵血政策", "c": "俾斯麥主導德意志統一的路線，強調以軍事與現實政治而非議會辯論達成統一。", "u": "b3c2.html#terms"}, {"k": "年代・1215", "t": "英國《大憲章》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1517", "t": "馬丁‧路德《九十五條論綱》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1543", "t": "哥白尼《天體運行論》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1600", "t": "英國東印度公司成立", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1648", "t": "《西發里亞和約》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1687", "t": "牛頓《自然哲學的數學原理》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1688", "t": "英國光榮革命", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1689", "t": "英國《權利法案》；洛克發表《政府論》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1769", "t": "阿克萊特發明水力紡紗機", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1776", "t": "北美發布《獨立宣言》；亞當斯密《國富論》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1787", "t": "美國制定聯邦憲法", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1789", "t": "法國大革命爆發", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1804", "t": "《拿破崙法典》頒布", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1814–15", "t": "拿破崙退位、維也納會議", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1848", "t": "馬克思、恩格斯發表《共產黨宣言》", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1861", "t": "義大利王國成立", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "年代・1870–71", "t": "普法戰爭；德意志帝國成立", "c": "世界史　個人自由理性的追尋", "u": "b3c2.html#timeline"}, {"k": "世界史　第 3 章", "t": "伊斯蘭與世界", "c": "本章處理世界三大宗教之一的伊斯蘭教，以及伊斯蘭世界與西方長達千年的互動。伊斯蘭教七世紀興起於阿拉伯半島，靠著信仰、商業與軍事迅速擴張，在中古時期保存並發展了希臘古典學術、數學與醫學，成為東西文化的橋樑。十字軍運動、鄂圖曼帝國的興衰、近代歐洲的殖民與石油政治，則一步步把兩個世界的關係推向今日中東問題的複雜局面。", "u": "b3c3.html"}, {"k": "世界史　3-1", "t": "伊斯蘭文化的發展與擴張", "c": "興起背景與穆罕默德；信仰核心；擴張與帝國；文化成就", "u": "b3c3.html#s31"}, {"k": "世界史　3-2", "t": "伊斯蘭世界與西方的互動", "c": "十字軍運動；鄂圖曼帝國；近代的衝擊與回應", "u": "b3c3.html#s32"}, {"k": "關鍵詞・世界史", "t": "《古蘭經》", "c": "伊斯蘭教經典，被視為真主透過天使降示給穆罕默德的直接啟示。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "聖遷", "c": "622 年穆罕默德自麥加遷往麥地那，為伊斯蘭曆元年的起點。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "六信五功", "c": "六信指信真主、天使、經典、先知、後世、前定；五功為念、禮、齋、課、朝。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "哈里發", "c": "穆罕默德逝世後的繼承者，兼具宗教與政治領導地位。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "遜尼派與什葉派", "c": "因哈里發繼承問題分裂：遜尼派承認共議推舉，什葉派主張須出自阿里一系。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "有經人", "c": "伊斯蘭統治下的猶太教徒、基督徒等，可保有信仰但須繳納人頭稅。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "智慧宮", "c": "阿拔斯王朝於巴格達設立的學術機構，大規模翻譯希臘、波斯、印度典籍。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "伊本‧西那（阿維森納）", "c": "中世紀伊斯蘭醫學家，《醫典》長期為歐洲醫學教科書。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "十字軍運動", "c": "1096–1291 年西歐以奪回聖地為名發動的一系列東征，軍事失敗但促進東西交流。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "米利特制", "c": "鄂圖曼帝國允許不同宗教社群自治的制度，維繫多元族群統治。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "坦志麥特", "c": "十九世紀鄂圖曼引進西式法律、軍事與教育的改革運動。", "u": "b3c3.html#terms"}, {"k": "關鍵詞・世界史", "t": "世俗化", "c": "將宗教與國家事務分離的過程；凱末爾在土耳其推動的改革為典型案例。", "u": "b3c3.html#terms"}, {"k": "年代・570 前後", "t": "穆罕默德出生於麥加", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・610", "t": "穆罕默德開始傳教", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・622", "t": "聖遷（伊斯蘭曆元年）", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・630", "t": "穆罕默德重返麥加", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・632", "t": "穆罕默德逝世，哈里發時期開始", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・661", "t": "倭馬亞王朝建立，定都大馬士革", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・711", "t": "穆斯林進入伊比利半島", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・750", "t": "阿拔斯王朝建立，後定都巴格達", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1096–1291", "t": "十字軍運動", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1258", "t": "蒙古攻陷巴格達，阿拔斯王朝滅亡", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1299", "t": "鄂圖曼帝國興起", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1453", "t": "鄂圖曼攻陷君士坦丁堡，拜占庭滅亡", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1520–66", "t": "蘇萊曼一世在位，鄂圖曼鼎盛", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1839 起", "t": "鄂圖曼推行坦志麥特改革", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1923", "t": "土耳其共和國成立，凱末爾推動世俗化", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1948", "t": "以色列建國，第一次以阿戰爭", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "年代・1973", "t": "第四次以阿戰爭引發石油危機", "c": "世界史　伊斯蘭與世界", "u": "b3c3.html#timeline"}, {"k": "世界史　第 4 章", "t": "西方與世界", "c": "本章處理近五百年來「西方主導世界」的形成與鬆動。從大航海時代的新航路與哥倫布大交換開始，歐洲把美洲、非洲、亞洲串進同一個貿易體系；工業化之後的新帝國主義，使殖民統治在十九世紀達到頂峰。兩次世界大戰既是歐洲內部矛盾的總爆發，也重創了殖民母國的元氣，最終為二十世紀中期的反殖民與民族獨立浪潮打開空間。", "u": "b3c4.html"}, {"k": "世界史　4-1", "t": "歐洲與亞洲的交流", "c": "大航海時代的開啟；哥倫布大交換；歐洲與東亞的接觸", "u": "b3c4.html#s41"}, {"k": "世界史　4-2", "t": "西方殖民帝國與世界的互動", "c": "從商業殖民到新帝國主義；殖民統治的手段與後果", "u": "b3c4.html#s42"}, {"k": "世界史　4-3", "t": "兩次世界大戰", "c": "第一次世界大戰；戰間期與第二次世界大戰", "u": "b3c4.html#s43"}, {"k": "世界史　4-4", "t": "現代反殖民運動的發展", "c": "反殖民的思想與條件；各地的獨立路徑；去殖民之後", "u": "b3c4.html#s44"}, {"k": "關鍵詞・世界史", "t": "哥倫布大交換", "c": "新舊大陸之間作物、牲畜、人口與疾病的大規模互相流動，徹底改變全球生態與人口結構。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "馬尼拉大帆船貿易", "c": "西班牙以馬尼拉為中繼，將美洲白銀輸往中國、換取絲綢瓷器的跨太平洋貿易。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "三角貿易", "c": "歐洲工業品換非洲奴隸、奴隸運往美洲生產原料、原料再運回歐洲的大西洋貿易結構。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "新帝國主義", "c": "十九世紀後期列強為原料與市場深入殖民內陸的擴張浪潮，以柏林會議瓜分非洲為代表。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "文明使命", "c": "殖民者用以合理化擴張的說法，主張其統治能把「文明」帶給被殖民者。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "社會達爾文主義", "c": "將生物演化的競爭觀套用於人類社會與種族，被用來合理化殖民與擴張。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "總體戰", "c": "動員全國人力、物力與輿論支援戰爭，使平民與前線的界線模糊。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "《凡爾賽和約》", "c": "1919 年對德國課以賠償與領土限制的條約，其嚴苛條件被視為二戰的遠因之一。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "綏靖政策", "c": "1930 年代英法對德義擴張採取讓步以求和平的作法，以慕尼黑協定為代表。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "大屠殺", "c": "納粹對猶太人的系統性屠殺，造成約六百萬人死亡。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "民族自決", "c": "一戰後提出的原則，主張民族有權決定自己的政治歸屬，鼓舞了殖民地的獨立要求。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "不結盟運動", "c": "冷戰期間新興國家拒絕加入美蘇任一陣營的集體行動，源於 1955 年萬隆會議。", "u": "b3c4.html#terms"}, {"k": "關鍵詞・世界史", "t": "新殖民主義", "c": "指政治獨立後，舊宗主國仍透過資本、市場與技術延續影響力的現象。", "u": "b3c4.html#terms"}, {"k": "年代・1492", "t": "哥倫布抵達美洲", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1498", "t": "達伽馬抵達印度", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1519–22", "t": "麥哲倫船隊完成環球航行", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1600", "t": "英國東印度公司成立", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1602", "t": "荷蘭東印度公司成立", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1807/1833", "t": "英國先後禁止奴隸貿易與廢除奴隸制", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1839–42", "t": "鴉片戰爭", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1884–85", "t": "柏林會議，列強議定瓜分非洲", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1914", "t": "塞拉耶佛事件，第一次世界大戰爆發", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1917", "t": "美國參戰；俄國十月革命", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1919", "t": "巴黎和會與《凡爾賽和約》", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1929", "t": "經濟大恐慌", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1939", "t": "德國入侵波蘭，第二次世界大戰爆發", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1941", "t": "德軍進攻蘇聯；日本偷襲珍珠港", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1945", "t": "德日投降；聯合國成立", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1947", "t": "印度、巴基斯坦分治獨立", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1955", "t": "萬隆會議", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "年代・1960", "t": "非洲年，17 國獨立", "c": "世界史　西方與世界", "u": "b3c4.html#timeline"}, {"k": "世界史　第 5 章", "t": "冷戰及後冷戰時期的世界局勢", "c": "本章處理二戰結束到蘇聯解體的世界格局。美蘇從盟友變成對手，以意識形態、軍備、太空與代理人戰爭全面較勁，世界被切成兩個陣營，臺灣、韓國、越南都被捲入其中。1960 年代以後，民權運動、反戰運動、學生運動與女性主義從內部鬆動了兩大陣營的正當性；1989 年柏林圍牆倒塌、1991 年蘇聯解體，冷戰以出乎意料的和平方式結束，卻也留下許多至今未解的區域衝突。", "u": "b3c5.html"}, {"k": "世界史　5-1", "t": "美、蘇冷戰的形成與發展", "c": "冷戰如何形成；全球對抗的形式；冷戰下的東亞與臺灣", "u": "b3c5.html#s51"}, {"k": "世界史　5-2", "t": "政治社會運動與冷戰的終結", "c": "1960 年代的社會運動浪潮；共產陣營的鬆動；冷戰的終結", "u": "b3c5.html#s52"}, {"k": "關鍵詞・世界史", "t": "鐵幕", "c": "邱吉爾用以形容歐洲被共產與非共產陣營分隔的界線。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "杜魯門主義", "c": "1947 年美國宣示援助自由國家、圍堵共產主義擴張的政策。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "馬歇爾計畫", "c": "美國對西歐的大規模經濟援助計畫，兼有重建與鞏固陣營的雙重目的。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "北大西洋公約組織（NATO）", "c": "1949 年成立的西方集體防衛組織，與華沙公約組織對峙。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "相互保證毀滅", "c": "美蘇核武均足以摧毀對方，因此誰也不敢先發動核戰的恐怖平衡。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "代理人戰爭", "c": "超強不直接交戰，而支持第三地的不同勢力作戰，如韓戰、越戰、阿富汗戰爭。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "古巴飛彈危機", "c": "1962 年蘇聯在古巴部署飛彈引發的對峙，是冷戰最接近核戰的時刻。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "民權運動", "c": "1950–60 年代美國爭取種族平等的社會運動，金恩博士為代表人物。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "布拉格之春", "c": "1968 年捷克斯洛伐克的政治改革嘗試，遭蘇聯武力鎮壓。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "團結工聯", "c": "1980 年波蘭興起的獨立工會，直接挑戰共產政權，是東歐劇變的先聲。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "重建與開放", "c": "戈巴契夫推動的經濟重整與政治公開化政策，意外加速了蘇聯瓦解。", "u": "b3c5.html#terms"}, {"k": "關鍵詞・世界史", "t": "歷史的終結", "c": "冷戰結束後有學者主張自由民主已是人類制度的終點，此說後來受到廣泛挑戰。", "u": "b3c5.html#terms"}, {"k": "年代・1945", "t": "二戰結束，聯合國成立", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1946", "t": "邱吉爾發表「鐵幕」演說", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1947", "t": "杜魯門主義與馬歇爾計畫", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1948–49", "t": "柏林封鎖與空運", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1949", "t": "NATO 成立；中華人民共和國成立；中華民國政府遷臺", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1950–53", "t": "韓戰", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1955", "t": "華沙公約組織成立", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1956", "t": "匈牙利事件", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1957", "t": "蘇聯發射史普尼克衛星", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1961", "t": "柏林圍牆興建", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1962", "t": "古巴飛彈危機", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1964", "t": "美國《民權法案》通過", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1968", "t": "布拉格之春；法國五月風暴", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1969", "t": "阿波羅十一號登月", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1971", "t": "中華民國退出聯合國", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1975", "t": "越戰結束", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1979", "t": "美中建交、美臺斷交；蘇聯入侵阿富汗", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1985", "t": "戈巴契夫推動重建與開放", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1989", "t": "東歐劇變，柏林圍牆倒塌", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "年代・1991", "t": "蘇聯解體，冷戰結束", "c": "世界史　冷戰及後冷戰時期的世界局勢", "u": "b3c5.html#timeline"}, {"k": "世界史　第 6 章", "t": "當代世界新局面", "c": "本章收束全冊：先釐清什麼是「現代性」與「現代主義」，再看非西方世界如何回應西方主導的現代化，最後處理全球化帶來的機會與矛盾。理性、進步、工業化與都市化構成現代性的核心，但二十世紀的兩次大戰與環境危機也讓人反省它的代價。從伊斯蘭復興、後殖民思潮到本土化運動，「反西方」其實常常是用現代的方式反對現代；而全球化下的移動、流行文化與氣候議題，正是你我每天在經歷的歷史。", "u": "b3c6.html"}, {"k": "世界史　6-1", "t": "現代性與現代文化", "c": "什麼是現代性；現代主義的反省", "u": "b3c6.html#s61"}, {"k": "世界史　6-2", "t": "西方與反西方", "c": "非西方世界的回應；後殖民與文化認同", "u": "b3c6.html#s62"}, {"k": "世界史　6-3", "t": "全球化與多元文化", "c": "全球化的面向；同質化還是在地化；當代課題", "u": "b3c6.html#s63"}, {"k": "關鍵詞・世界史", "t": "現代性", "c": "近代歐洲結構性變革的特徵：理性、進步、個人權利、工業化與都市化。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "現代主義", "c": "十九世紀末興起的文化思潮，挑戰傳統與理性獨斷，重視主觀感受與經驗。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "世俗化", "c": "宗教在公共生活中的影響力下降、政教分離的過程。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "伊斯蘭復興運動", "c": "對世俗化與外來干預的回應，主張回歸伊斯蘭原則重整社會。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "後殖民", "c": "檢討殖民經驗如何持續影響被殖民社會的知識、認同與制度的思潮。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "文明衝突論", "c": "主張後冷戰的主要衝突來自文化與文明差異的說法，因過度簡化而廣受批評。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "全球化", "c": "資本、人口、資訊與文化跨越國界高速流動，使各地相互依存的過程。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "全球在地化", "c": "全球元素在地方被改造並與在地文化結合的現象，強調全球思維、在地行動。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "多元文化主義", "c": "主張承認並尊重社會中不同文化群體的價值與權利。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "反全球化", "c": "對全球化造成的不平等、環境破壞與文化衝擊提出質疑的各種運動。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "歐洲聯盟", "c": "由歐洲經濟共同體發展而成的區域整合組織，1993 年正式成立。", "u": "b3c6.html#terms"}, {"k": "關鍵詞・世界史", "t": "英國脫歐", "c": "英國於 2016 年公投決定退出歐盟，2020 年正式生效。", "u": "b3c6.html#terms"}, {"k": "年代・1870 年代起", "t": "第二次工業革命，都市化加速", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1900 前後", "t": "現代主義藝術與文學興起", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1945", "t": "二戰結束，進步觀受到根本質疑", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1948", "t": "《世界人權宣言》", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1957", "t": "歐洲經濟共同體成立（歐盟前身）", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1989–91", "t": "冷戰結束", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1993", "t": "歐洲聯盟正式成立", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・1995", "t": "世界貿易組織（WTO）成立", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・2001", "t": "美國九一一事件", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・2008", "t": "全球金融海嘯", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・2015", "t": "《巴黎氣候協定》", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・2016", "t": "英國公投決定脫歐", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "年代・2020", "t": "英國正式退出歐盟；COVID-19 全球大流行", "c": "世界史　當代世界新局面", "u": "b3c6.html#timeline"}, {"k": "科技環境與藝術　第 1 章", "t": "疾病與醫療", "c": "本章以疾病為線索，觀察醫療知識與社會權力如何交纏。傳統社會不論中西，多半把疾病視為身體內部平衡被打破的結果，中醫講陰陽、氣血與五行，西方則長期沿用希波克拉底與蓋倫的四體液說。黑死病、天花與一九一八年流感等大疫，不只帶走人口，也改變了勞動力結構、宗教權威與國家治理的方式。十九世紀細菌致病學說成立後，衛生從個人德行變成國家事務，公共衛生與殖民統治更在許多地方結合成一套管理身體的技術，日治臺灣即是明顯案例。最後，戰後的防疫體系、全民健保，以及 SARS 與 COVID-19 的經驗，把「防疫」與「自由」的拉鋸推到我們這一代人眼前。", "u": "b4c1.html"}, {"k": "科技環境與藝術　1-1", "t": "傳統社會怎麼理解疾病", "c": "中醫：把身體看成一個小宇宙；四體液說：西方醫學的千年主流；瘴氣、風水與宗教解釋；醫者是誰？醫療的社會位置", "u": "b4c1.html#s11"}, {"k": "科技環境與藝術　1-2", "t": "瘟疫如何改寫歷史", "c": "黑死病與中古歐洲的崩解；天花：帝國的隱形武器與人類的第一場勝利；一九一八年流感：全球化時代的第一場大流行；疫病的長期效應：不只是死亡數字", "u": "b4c1.html#s12"}, {"k": "科技環境與藝術　1-3", "t": "細菌學說、公共衛生與殖民醫學", "c": "看見看不見的敵人；從個人衛生到國家事務；殖民醫學：治療，也是統治；日治臺灣的公共衛生工程", "u": "b4c1.html#s13"}, {"k": "科技環境與藝術　1-4", "t": "戰後臺灣與新興傳染病的挑戰", "c": "戰後防疫體系的重建；從疾病治療到健康保險；SARS：一次昂貴的預演；COVID-19 的歷史視角", "u": "b4c1.html#s14"}, {"k": "關鍵詞・科技環境與藝術", "t": "四體液說", "c": "古希臘以來的西方醫學理論，認為血液、黏液、黃膽汁、黑膽汁失衡即生病，經蓋倫整理後主導歐洲醫學千餘年。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "辨證論治", "c": "中醫依病人整體症狀組合判斷病機並給方，而非只針對單一症狀，《傷寒雜病論》是重要奠基之作。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "瘴氣說", "c": "認為腐敗物質散發的穢濁空氣會致病。雖然病因判斷錯誤，卻促成近代都市清潔與下水道建設。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "檢疫（quarantine）", "c": "源自黑死病時期要求疫區船隻在外海停泊觀察四十日的做法，是最早的國際防疫制度。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "細菌致病學說", "c": "十九世紀由巴斯德、科赫等人確立，主張特定微生物造成特定疾病，使醫學走向病原辨識與阻斷。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "科赫假說", "c": "科赫提出的驗證原則：病原須見於所有病例、可分離培養、接種後致病、並能再分離出同一病原。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "疫苗（vaccine）", "c": "源自金納以牛痘預防天花的實驗，字根來自拉丁文的「牛」，指以人工方式誘發免疫力。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "流行病學", "c": "研究疾病在人群中分布與影響因素的學問，史諾的倫敦霍亂地圖是常被引用的起點。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "公醫制度", "c": "日治臺灣由總督府派駐受現代醫學訓練的醫師於各地，兼辦診療、防疫與衛生調查的制度。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "生物學原則", "c": "後藤新平的施政主張：治理必須先調查當地既有習慣與條件，再依實際狀況設計制度，不可強行移植。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "熱帶醫學", "c": "十九世紀後期發展的專門領域，研究熱帶地區疾病，與歐洲殖民擴張關係密切。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "全民健康保險", "c": "一九九五年開辦，以強制納保、單一保險人方式把全體國民納入同一風險分攤機制。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "中央流行疫情指揮中心", "c": "SARS 後修法明確化的緊急應變機制，疫情達一定等級時成立，統籌跨部會防疫決策。", "u": "b4c1.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "國際關注的公共衛生緊急事件", "c": "世界衛生組織依《國際衛生條例》所作的最高層級警示，觸發成員國的通報與應變義務。", "u": "b4c1.html#terms"}, {"k": "年代・約前 400", "t": "希波克拉底學派主張疾病有自然原因", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・戰國至西漢", "t": "《黃帝內經》陸續成篇", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・約 200", "t": "張仲景《傷寒雜病論》問世", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・2 世紀", "t": "蓋倫整理體液學說，影響歐洲逾千年", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1347–1351", "t": "黑死病橫掃歐洲，檢疫制度出現", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1596", "t": "李時珍《本草綱目》刊行", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1796", "t": "金納進行牛痘接種實驗", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1848", "t": "英國制定《公共衛生法》", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1854", "t": "史諾以霍亂地圖指出汙染水源", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1867", "t": "李斯特提倡外科消毒", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1882", "t": "科赫發現結核桿菌", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1896", "t": "鼠疫傳入臺灣，總督府展開防疫", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1898", "t": "後藤新平出任臺灣總督府民政長官", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1899", "t": "臺灣總督府醫學校設立", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1918–1919", "t": "流感全球大流行", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1965", "t": "世界衛生組織確認臺灣根除瘧疾", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1980", "t": "世界衛生組織宣布天花根除", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・1995", "t": "臺灣全民健康保險開辦", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・2003", "t": "SARS 疫情，和平醫院封院", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "年代・2020–2023", "t": "COVID-19 全球大流行", "c": "科技環境與藝術　疾病與醫療", "u": "b4c1.html#timeline"}, {"k": "科技環境與藝術　第 2 章", "t": "科技與社會", "c": "本章以技術為線索，觀察科技與社會如何互相形塑。火藥、印刷術與指南針源於東亞，傳入歐洲後卻在不同的社會條件下產生了改變世界的效果，說明技術的影響取決於它落在什麼樣的社會裡。工業革命把動力從人畜與水風轉為煤與蒸汽，工廠制度重新切割了時間與空間；鐵路、電報與電話壓縮了距離，電力與石油則支撐起二十世紀的都市生活。二十世紀後半的電晶體、積體電路與網際網路帶來資訊革命，臺灣也在其中找到半導體代工的位置。最後，核能、資料隱私與人工智慧提醒我們：技術能做什麼，和技術應該做什麼，是兩個不同的問題。", "u": "b4c2.html"}, {"k": "科技環境與藝術　2-1", "t": "從三大發明到機械時代", "c": "火藥、印刷、指南針的旅程；工業革命為什麼發生在英國；機械化改寫的社會關係", "u": "b4c2.html#s21"}, {"k": "科技環境與藝術　2-2", "t": "距離的消失：交通、通訊與能源", "c": "鐵路與輪船縮短了世界；電報與電話：訊息比人先到；電力與石油撐起的二十世紀", "u": "b4c2.html#s22"}, {"k": "科技環境與藝術　2-3", "t": "資訊革命與臺灣的位置", "c": "從真空管到積體電路；網際網路與數位生活；臺灣如何切進半導體產業；科技倫理與人工智慧", "u": "b4c2.html#s23"}, {"k": "關鍵詞・科技環境與藝術", "t": "活字印刷", "c": "以可重複排列的單字模組版印刷。歐洲金屬活字大幅降低書價，助長識字率、宗教改革與民族語言文學。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "工廠制度", "c": "把勞動者集中於固定場所、依鐘點與分工運作的生產方式，改變了工作節奏與家庭生活。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "盧德運動", "c": "十九世紀初英國工人破壞紡織機的行動，核心訴求是工作與生計，而非反對機器本身。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "標準時間", "c": "鐵路時刻表需求下形成的統一時間制度，取代各地依日照制定的地方時。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "第二次工業革命", "c": "十九世紀後期以電力、石油、化工與鋼鐵為主的技術變革，特徵是科學研究直接導入生產。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "裝配線", "c": "福特導入的量產方式，工件移動、工人固定於單一工序，大幅降低單位成本，也讓勞動趨於單調。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "電晶體", "c": "一九四七年問世的半導體元件，取代真空管，是電子產品微型化的基礎。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "積體電路", "c": "把多個電子元件整合於單一半導體晶片，使運算能力密度快速提升。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "摩爾定律", "c": "晶片上元件數量約每隔一段時間倍增的經驗性觀察，長期作為半導體產業的投資節奏參考。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "封包交換", "c": "把資料切成小封包分別傳送、在終端重組的通訊方式，是網際網路去中心化設計的基礎。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "晶圓代工", "c": "只承接製造、不推出自有品牌產品的半導體經營模式，由台積電開創，改變了全球產業分工。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "科學園區", "c": "以租稅優惠、基礎設施與人才聚集吸引高科技廠商進駐的產業政策工具，新竹為臺灣首座。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "演算法偏見", "c": "人工智慧因訓練資料或設計方式，複製甚至放大社會既有歧視的現象。", "u": "b4c2.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "技術決定論", "c": "認為技術本身直接決定社會走向的觀點。科技史研究多半主張技術與社會條件是互相形塑的。", "u": "b4c2.html#terms"}, {"k": "年代・唐代", "t": "火藥於煉丹過程中被發現，雕版印刷出現", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・北宋", "t": "畢昇發明泥活字；指南針用於航海", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・14 世紀", "t": "歐洲出現火砲，傳統城堡防禦優勢下降", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・約 1450", "t": "古騰堡以金屬活字印刷《聖經》", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1769", "t": "瓦特取得蒸汽機改良專利", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1830", "t": "利物浦至曼徹斯特鐵路通車", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1844", "t": "摩斯電報線路啟用", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1859", "t": "美國賓州鑽出商業油井", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1866", "t": "跨大西洋海底電纜成功運作", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1869", "t": "蘇伊士運河通航", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1876", "t": "貝爾取得電話專利", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1879", "t": "愛迪生改良白熾燈", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1913", "t": "福特汽車導入裝配線量產", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1947", "t": "電晶體問世", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1966", "t": "高雄加工出口區設立", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1973", "t": "工業技術研究院成立", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1980", "t": "新竹科學工業園區成立", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1987", "t": "台積電成立，開創晶圓代工模式", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・1990 年代", "t": "全球資訊網普及，網路進入日常生活", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "年代・2007", "t": "智慧型手機問世，行動上網快速擴散", "c": "科技環境與藝術　科技與社會", "u": "b4c2.html#timeline"}, {"k": "科技環境與藝術　第 3 章", "t": "物種與文明", "c": "本章從物種的角度重讀人類史。約一萬年前，人類在數個地區各自開始栽培作物與畜養動物，定居、人口成長、階層分化與疾病都隨之而來。一四九二年之後展開的哥倫布大交換，讓作物、牲畜與病原在新舊大陸之間大規模流動，既養活了更多人口，也帶來美洲原住民社會的崩解。糖、茶、咖啡、橡膠等經濟作物把熱帶地區編入全球市場，種植園與奴隸貿易是其制度基礎。臺灣的甘蔗、蓬萊米與吳郭魚，同樣是政策、市場與生態交互作用的產物。最後，外來種與生物多樣性的課題，提醒我們物種的移動從來沒有停止，後果也還在累積。", "u": "b4c3.html"}, {"k": "科技環境與藝術　3-1", "t": "農業起源與馴化", "c": "人類為什麼開始種田；農業帶來的不只是溫飽；作物與帝國", "u": "b4c3.html#s31"}, {"k": "科技環境與藝術　3-2", "t": "哥倫布大交換", "c": "兩個世界的碰撞；疾病與人口崩解；單一作物的風險：愛爾蘭大饑荒", "u": "b4c3.html#s32"}, {"k": "科技環境與藝術　3-3", "t": "經濟作物、種植園與世界市場", "c": "糖：從奢侈品到日用品；茶與咖啡：飲料如何牽動國際政治；橡膠：熱帶雨林的工業原料", "u": "b4c3.html#s33"}, {"k": "科技環境與藝術　3-4", "t": "臺灣的物種引進與生態課題", "c": "甘蔗：從荷治貿易到製糖會社；蓬萊米與稻作改良；外來種：好意與後果；生物多樣性與保育制度", "u": "b4c3.html#s34"}, {"k": "關鍵詞・科技環境與藝術", "t": "馴化", "c": "人類長期選育使動植物性狀改變並依賴人類生存的過程，作物與人類其實是互相改造。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "新月沃地", "c": "西亞自兩河流域延伸至地中海東岸的弧形地帶，是小麥、大麥與綿羊、山羊最早被馴化之處。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "哥倫布大交換", "c": "一四九二年後美洲與歐亞非之間作物、家畜、人群與病原的大規模交換，深刻改變全球生態與人口。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "處女地流行病", "c": "從未接觸過某病原的人群初次遭遇時所引發的高致死率流行，美洲原住民的人口崩解為典型。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "單一栽培", "c": "大面積種植單一作物甚至單一品種的生產方式，效率高但對病蟲害與價格波動極為脆弱。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "種植園", "c": "以大面積土地、強制或廉價勞力生產單一經濟作物並輸出的生產組織，是殖民經濟的核心形式。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "三角貿易", "c": "歐洲工業品運往非洲、非洲奴隸運往美洲、美洲原料運回歐洲的循環貿易結構。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "經濟作物", "c": "主要供出口與加工而非自用的作物，如糖、茶、咖啡、橡膠，其價格由國際市場決定。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "外來入侵種", "c": "被引入原分布範圍以外並大量繁殖、造成生態或經濟損害的物種，如福壽螺、小花蔓澤蘭。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "原料採取區域", "c": "日治臺灣規定蔗農只能將甘蔗售予指定製糖會社的制度，使會社取得壟斷收購的地位。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "米糖相剋", "c": "稻米與甘蔗爭奪同一土地與水源，農民依價格在兩者間轉換，牽動殖民地農業布局的現象。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "蓬萊米", "c": "日治時期在臺育成、適合在臺栽培的粳稻品種，一九二六年定名，大量輸往日本。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "生物多樣性", "c": "包含基因、物種與生態系三個層次的多樣程度，多樣性愈高，系統的抵抗與恢復力愈強。", "u": "b4c3.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "《生物多樣性公約》", "c": "一九九二年里約地球高峰會通過，處理物種保育、永續利用與遺傳資源利益分享。", "u": "b4c3.html#terms"}, {"k": "年代・約前 10000", "t": "西亞新月沃地出現最早的農耕與畜養", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・約前 8000–前 6000", "t": "東亞栽培粟與稻，中美洲馴化玉米", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・約 5 世紀", "t": "印度發展出蔗汁結晶的製糖技術", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・7–8 世紀", "t": "阿拉伯人把甘蔗與製糖技術帶往地中海", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1492", "t": "哥倫布抵達美洲，大交換展開", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・16 世紀", "t": "天花等舊大陸疾病重創美洲原住民社會", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・17 世紀", "t": "加勒比海與巴西糖業種植園擴張，奴隸貿易大增", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1624–1662", "t": "荷蘭統治臺灣，獎勵蔗作並引進黃牛", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1773", "t": "波士頓茶葉事件", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1840 年代", "t": "愛爾蘭馬鈴薯晚疫病造成大饑荒", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1859", "t": "野兔被引入澳洲，日後釀成外來種災難", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1870 年代", "t": "橡膠種子運出巴西，移植東南亞", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1901", "t": "新渡戶稻造提出臺灣糖業改良意見書", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1905", "t": "臺灣實施原料採取區域制度", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1925", "t": "二林蔗農事件", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1926", "t": "臺灣新育成稻米品種定名為「蓬萊米」", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1946", "t": "吳振輝、郭啟彰引進吳郭魚", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1970 年代末", "t": "福壽螺引進臺灣養殖，後成為農業害蟲", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1989", "t": "臺灣制定《野生動物保育法》", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "年代・1992", "t": "里約地球高峰會通過《生物多樣性公約》", "c": "科技環境與藝術　物種與文明", "u": "b4c3.html#timeline"}, {"k": "科技環境與藝術　第 4 章", "t": "文明與環境", "c": "本章把環境當成歷史的主角之一。氣候變動曾在小冰期等時段對農業與政局造成壓力，水利工程則讓文明得以在乾旱或洪泛區生存，但同時帶來鹽化、淤積與社會動員的成本。森林砍伐與資源耗竭是許多社會的長期難題，工業革命之後更以化石燃料的形式全面加速。倫敦大煙霧、水俁病等公害事件，使汙染從地方問題升級為國家立法的對象。臺灣自一九七〇年代末以來，也經歷米糠油中毒、反杜邦、反五輕、六輕與核能等一連串爭論。最後，從斯德哥爾摩會議到《巴黎協定》與淨零排放，環境治理已成為國際政治的核心議題。", "u": "b4c4.html"}, {"k": "科技環境與藝術　4-1", "t": "氣候、水與文明的條件", "c": "小冰期：氣候如何進入歷史；治水：文明的基礎工程；臺灣的水利與土地", "u": "b4c4.html#s41"}, {"k": "科技環境與藝術　4-2", "t": "資源耗竭與能源轉換", "c": "森林：文明最早耗盡的資源；從木柴到化石燃料；共同資源為何容易被耗盡", "u": "b4c4.html#s42"}, {"k": "科技環境與藝術　4-3", "t": "工業汙染與公害", "c": "倫敦大煙霧與空氣立法；水俁病與公害的認定；環境意識的覺醒", "u": "b4c4.html#s43"}, {"k": "科技環境與藝術　4-4", "t": "臺灣的環境議題與全球治理", "c": "臺灣環境運動的起點；六輕、空汙與水資源；核能：一個仍在辯論中的選項；從斯德哥爾摩到淨零排放", "u": "b4c4.html#s44"}, {"k": "關鍵詞・科技環境與藝術", "t": "小冰期", "c": "約十四至十九世紀中葉北半球氣溫偏低的時期，農作歉收與社會動盪風險上升。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "十七世紀危機", "c": "指十七世紀全球普遍出現戰亂、饑荒與政權更替的現象，部分學者將其與小冰期氣候連結，仍屬學界討論中的解釋。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "土壤鹽化", "c": "灌溉後排水不良，水分蒸發使鹽分累積於表土，導致作物難以生長，是古代灌溉文明的長期難題。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "三年輪作", "c": "嘉南大圳因水量有限而採行的制度，區域內稻、蔗與雜作輪替，使有限水源能輪流灌溉。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "公有地悲劇", "c": "缺乏明確權屬與管理的共同資源，因各方追求自身最大利益而被過度使用、終致枯竭。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "外部成本", "c": "生產或消費造成、卻未反映在價格上的社會成本，如汙染與資源耗竭，是環境政策要處理的核心問題。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "公害", "c": "企業或設施造成、影響不特定多數人健康與生活環境的汙染損害，水俁病為代表性案例。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "《寂靜的春天》", "c": "卡森一九六二年出版，揭露農藥在食物鏈中累積的危害，被視為現代環境運動的起點之一。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "環境正義", "c": "關注汙染負擔與環境風險是否不成比例地集中於弱勢社區的公平性議題。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "鄰避效應", "c": "民眾認同某些設施有必要存在，卻反對設置於自家附近的現象，常見於焚化爐、變電所與處置場。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "永續發展", "c": "一九八七年報告提出：滿足當代需求，同時不損及後代滿足其需求的能力。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "共同但有差別的責任", "c": "氣候公約原則：各國都應減量，但已開發國家因歷史排放較多而應負較大責任。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "《巴黎協定》", "c": "二〇一五年通過，改由各國自訂減量貢獻，並以控制全球升溫幅度為共同目標。", "u": "b4c4.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "淨零排放", "c": "使人為溫室氣體排放量與移除量相抵，臺灣已於二〇二三年將二〇五〇年淨零目標入法。", "u": "b4c4.html#terms"}, {"k": "年代・約前 3000", "t": "兩河流域大規模灌溉，土壤鹽化問題逐漸浮現", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・約前 256", "t": "蜀郡守李冰主持修築都江堰", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・約 1300–1850", "t": "北半球進入小冰期", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1719", "t": "彰化八堡圳完工", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・18 世紀後期", "t": "英國以煤取代木材，化石燃料時代展開", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1930", "t": "嘉南大圳與烏山頭水庫完工", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1952", "t": "倫敦大煙霧事件", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1956", "t": "英國制定《清淨空氣法》", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1962", "t": "卡森《寂靜的春天》出版", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1968", "t": "日本政府正式認定水俁病為公害病", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1972", "t": "聯合國人類環境會議在斯德哥爾摩召開", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1979", "t": "臺灣多氯聯苯食用油汙染事件", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1986", "t": "車諾比核電廠事故；鹿港反杜邦運動", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1987", "t": "《我們共同的未來》提出永續發展；臺灣環保署成立", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1992", "t": "里約地球高峰會，通過《聯合國氣候變化綱要公約》", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・1997", "t": "《京都議定書》通過", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・2011", "t": "日本福島核電廠事故", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・2015", "t": "《巴黎協定》通過；聯合國提出永續發展目標", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・2021", "t": "臺灣遭遇嚴重乾旱；核四商轉公投未通過", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "年代・2023", "t": "臺灣《氣候變遷因應法》公布，明定二〇五〇淨零目標", "c": "科技環境與藝術　文明與環境", "u": "b4c4.html#timeline"}, {"k": "科技環境與藝術　第 5 章", "t": "藝術與人文", "c": "本章把藝術放回它被製作與使用的社會脈絡。史前壁畫、神殿與宗教建築說明藝術長期承擔儀式、教化與權力展示的功能。文藝復興之後，宮廷、教會與富商的贊助制度決定了藝術家能畫什麼；學院與沙龍再進一步建立評價標準。十九世紀攝影術與印刷複製技術出現，寫實記錄不再是繪畫的專利，藝術家轉而追求光影、形式與主觀經驗，前衛運動甚至直接質疑「什麼才算藝術」。二十世紀的唱片、電影、廣播與電視催生了大眾文化，藝術與商品的界線變得模糊。臺灣的美術與文學則在殖民、戰後威權與解嚴的不同條件下，反覆處理「我們是誰」與「為誰而寫、為誰而畫」的問題。", "u": "b4c5.html"}, {"k": "科技環境與藝術　5-1", "t": "藝術為誰而作", "c": "最早的圖像：儀式、記錄與權力；宗教藝術的力量；贊助者、學院與市場", "u": "b4c5.html#s51"}, {"k": "科技環境與藝術　5-2", "t": "複製技術與藝術的轉向", "c": "攝影術的衝擊；複製時代的「原作」問題；前衛藝術：質疑藝術本身", "u": "b4c5.html#s52"}, {"k": "科技環境與藝術　5-3", "t": "大眾文化與流行音樂", "c": "從留聲機到串流；流行音樂與世代認同；普普藝術與商品美學", "u": "b4c5.html#s53"}, {"k": "科技環境與藝術　5-4", "t": "臺灣的美術、文學與文化資產", "c": "日治時期的美術舞臺；文學裡的臺灣意識；戰後美術的轉折；文化資產保存的難題", "u": "b4c5.html#s54"}, {"k": "關鍵詞・科技環境與藝術", "t": "贊助制度", "c": "由教會、宮廷或富商出資委託創作的制度，題材與規格常載明於契約，深刻影響作品面貌。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "學院與沙龍", "c": "官方美術機構與其定期展覽，建立題材位階與評選標準，長期決定藝術家的名聲與收入。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "落選者沙龍", "c": "一八六三年因大量作品落選引發不滿而另設的展覽，象徵官方品味的權威開始鬆動。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "印象派", "c": "十九世紀後期主張捕捉光線與瞬間感受的畫派，首展於一八七四年，起初評價不佳。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "靈光（aura）", "c": "班雅明用語，指原作因與特定時空綁定而具有的獨一性；機械複製使這種特質消散。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "機械複製", "c": "以攝影、印刷等技術大量再製圖像，改變了藝術的流通方式與觀看經驗。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "前衛藝術", "c": "刻意突破既有規範與定義的創作取向，達達、超現實主義與現成物都屬此脈絡。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "現成物", "c": "把日常物品直接置入藝術脈絡的作法，其重點在質疑「由誰認定藝術」的制度問題。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "普普藝術", "c": "一九六〇年代取材廣告、漫畫與商品圖像的藝術，模糊高級藝術與大眾文化的界線。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "臺展三少年", "c": "一九二七年臺灣美術展覽會首屆東洋畫部中入選的三位年輕臺籍畫家，因多位前輩落選而得名。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "鄉土文學論戰", "c": "一九七〇年代末臺灣文壇的重大論爭，焦點在文學是否應關注本土現實與社會階級。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "社區總體營造", "c": "一九九〇年代推動的政策，強調由居民自主發掘與維護在地文化，使保存的主體擴及社群。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "無形文化資產", "c": "傳統技藝、表演藝術、祭典與口傳知識等，須有人持續實作才能存續，保存難度高於建物。", "u": "b4c5.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "《世界遺產公約》", "c": "一九七二年由聯合國教科文組織通過，將文化與自然遺產的保存列為國際共同責任。", "u": "b4c5.html#terms"}, {"k": "年代・約前 17000", "t": "法國拉斯科洞窟壁畫繪製", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・約前 5 世紀", "t": "雅典帕德嫩神殿興建", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・4–14 世紀", "t": "敦煌莫高窟陸續開鑿", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・12–13 世紀", "t": "西歐哥德式主教座堂興起", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・15 世紀", "t": "麥地奇家族贊助佛羅倫斯藝術", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1648", "t": "法國成立皇家繪畫雕塑學院，確立學院與沙龍體制", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1839", "t": "法國公布達蓋爾銀版攝影法", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1863", "t": "巴黎舉辦落選者沙龍", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1874", "t": "印象派首次聯合展出", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1895", "t": "電影首次公開放映", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1907", "t": "畢卡索《亞維農的少女》，立體派出現", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1917", "t": "杜象以現成物挑戰藝術的定義", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1920", "t": "黃土水入選日本帝國美術展覽會", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1927", "t": "臺灣美術展覽會開辦，出現「臺展三少年」", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1936", "t": "班雅明發表〈機械複製時代的藝術作品〉", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1937", "t": "畢卡索完成《格爾尼卡》", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1957", "t": "五月畫會、東方畫會先後舉行首展，現代繪畫運動展開", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1972", "t": "聯合國教科文組織通過《世界遺產公約》", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1977–1978", "t": "臺灣鄉土文學論戰", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "年代・1982", "t": "臺灣制定《文化資產保存法》", "c": "科技環境與藝術　藝術與人文", "u": "b4c5.html#timeline"}, {"k": "科技環境與藝術　第 6 章", "t": "文化與生活", "c": "本章處理最貼近我們的歷史——衣食住行。史學界自二十世紀中葉起重視物質文化與日常生活，認為長期而緩慢的生活變化，比政治事件更能說明社會的深層結構。香料、糖、茶、咖啡與可樂的全球流動，說明飲食從來不只是口味問題，而是貿易路線、殖民體制與文化想像共同作用的結果。服裝標示身分，城市改造重新安排了人的移動與相遇，百貨公司、廣告與分期付款則塑造出消費社會。運動與休閒在十九世紀被制度化，成為現代國民與國族情感的載體。臺灣從日治的市區改正、戰後的美援飲食，一路走到便利商店、手搖飲與捷運生活，其中每一步都能看見全球趨勢在本地被改寫的痕跡。", "u": "b4c6.html"}, {"k": "科技環境與藝術　6-1", "t": "把日常當成史料", "c": "日常生活為什麼值得研究；衣：服裝如何標示身分；住與行：生活空間的改造", "u": "b4c6.html#s61"}, {"k": "科技環境與藝術　6-2", "t": "飲食的全球化", "c": "香料：推動航海的滋味；茶、咖啡與可樂的世界史；作物移動與人口變化", "u": "b4c6.html#s62"}, {"k": "科技環境與藝術　6-3", "t": "城市、休閒與消費社會", "c": "被重新規劃的城市；百貨公司、博覽會與廣告；運動與休閒的興起", "u": "b4c6.html#s63"}, {"k": "科技環境與藝術　6-4", "t": "臺灣日常生活的變遷", "c": "從美援到家電：戰後的生活基礎；校園、服裝與身體規訓；便利商店、手搖飲與夜市；媒體、交通與當代生活", "u": "b4c6.html#s64"}, {"k": "關鍵詞・科技環境與藝術", "t": "物質文化", "c": "以器物、建築、服飾與食物等實體遺留為對象的研究取向，補充文字史料的不足。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "日常生活史", "c": "關注長期而緩慢的生活變化，主張這些基礎結構比政治事件更能說明社會的運作。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "禁奢法", "c": "近代歐洲限制各階層可穿戴布料與飾品的法令，反映商業發展使身分界線鬆動的焦慮。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "香料貿易", "c": "中古以來連結南亞、西亞與歐洲的高價貿易，是促成地理大發現的重要動機之一。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "咖啡館", "c": "十七世紀後興起的社交場所，被視為近代公共輿論與商業資訊網絡形成的重要場域。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "市區改正", "c": "日治臺灣以拓寬道路、設置排水與公園為主的都市改造政策，奠定今日城市街廓的基礎。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "百貨公司", "c": "十九世紀中葉出現的零售形式，以明碼標價、自由進出與大量陳列把購物轉為休閒活動。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "世界博覽會", "c": "自一八五一年倫敦起舉辦的國際展示活動，兼有展現工業成果、國力與殖民地物產的功能。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "消費社會", "c": "以持續消費支撐經濟運作的社會型態，特徵包含廣告、品牌認同與信用分期制度。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "通勤", "c": "居住地與工作地分離後形成的每日往返，是大眾運輸普及後現代都市生活的典型節奏。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "在地化", "c": "全球流通的商品或文化進入某地後被改造以符合當地習慣的現象，速食菜單調整為常見例子。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "美援", "c": "一九五〇至六〇年代美國對臺經濟與物資援助，小麥與奶粉的輸入改變了臺灣的飲食結構。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "報禁", "c": "戒嚴時期限制報紙登記家數、張數與印製地點的政策，一九八八年解除後媒體環境大幅開放。", "u": "b4c6.html#terms"}, {"k": "關鍵詞・科技環境與藝術", "t": "夜市", "c": "集中於街道的小吃、遊戲與零售場所，是臺灣庶民消費與社交的重要空間與觀光意象。", "u": "b4c6.html#terms"}, {"k": "年代・15–17 世紀", "t": "香料貿易推動歐洲海外擴張", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・16 世紀後", "t": "玉米、番薯傳入歐亞，改變糧食結構", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・17 世紀", "t": "咖啡館在鄂圖曼與歐洲城市興起", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1851", "t": "倫敦舉辦第一屆世界博覽會", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1852", "t": "巴黎出現近代百貨公司", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1853–1870", "t": "巴黎進行大規模都市改造", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1863", "t": "英格蘭足球協會成立，運動規則化", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1886", "t": "可口可樂在美國問世", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1896", "t": "第一屆現代奧林匹克運動會在雅典舉行", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1900 年代", "t": "臺灣實施市區改正，城牆改為三線道路", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1931", "t": "嘉義農林學校棒球隊打進日本甲子園決賽", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1932", "t": "臺北菊元百貨、臺南林百貨開幕", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1962", "t": "臺灣電視公司開播", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1969", "t": "金龍少棒隊獲得世界少棒賽冠軍", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1970 年代末", "t": "臺灣出現第一批連鎖便利商店", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1984", "t": "臺灣第一家麥當勞在臺北開幕", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1988", "t": "報禁解除，媒體環境大幅開放", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1990", "t": "中華職業棒球聯盟開打", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・1996", "t": "臺北捷運首條路線通車", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "年代・2007", "t": "臺灣高速鐵路通車", "c": "科技環境與藝術　文化與生活", "u": "b4c6.html#timeline"}, {"k": "探究與實作　緒論／導論", "t": "序　歷史學探究：為何探究", "c": "這是一本動手做、用腦想的書。整學期要做的，是實際操作歷史書寫的每一個環節——從提出問題、蒐集材料、鑑別真偽、建立因果，到寫成一篇有憑有據的文章——並在過程中領略、發想與質疑背後的原理。你會發現：歷史不是「過去發生的事」，而是「後人依據證據對過去所做的解釋」。", "u": "b5c0.html"}, {"k": "探究與實作　0-1", "t": "這門課在做什麼", "c": "從讀者變成作者；歷史學的三個基本提問；本學期的工作流程", "u": "b5c0.html#s01"}, {"k": "關鍵詞・探究與實作", "t": "探究與實作", "c": "108 課綱加深加廣選修課程，強調學生親自操作學科的研究方法，而非接受現成結論。", "u": "b5c0.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "小論文", "c": "有明確問題意識、以史料為依據、依格式撰寫並標註引用的短篇研究文章。", "u": "b5c0.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "問題意識", "c": "研究者想弄清楚的具體疑問，是整篇論文的骨幹。", "u": "b5c0.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "APA 格式", "c": "本課程採用的書目與引註規範，目的是讓每一項證據都能被他人追溯查證。", "u": "b5c0.html#terms"}, {"k": "年代・第 1–2 週", "t": "認識歷史學：歷史是什麼", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 3–4 週", "t": "選題與問題意識", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 5–7 週", "t": "蒐集史料、鑑別史料", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 8–9 週", "t": "關鍵詞與概念界定", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 10–12 週", "t": "建立大綱與因果脈絡", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 13–15 週", "t": "歷史著作分析與寫作", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "年代・第 16–18 週", "t": "期末報告與口頭發表", "c": "探究與實作　序　歷史學探究：為何探究", "u": "b5c0.html#timeline"}, {"k": "探究與實作　第 1 章", "t": "歷史是什麼？", "c": "本章處理歷史學最根本的問題：歷史是「過去本身」，還是「關於過去的敘述」？我們會區分「史實」與「史觀」、「過去」與「歷史」，理解為什麼同一件事會有不同版本，以及這是否代表歷史沒有真假可言。答案是否定的：歷史容許多元解釋，但不容許沒有證據的主張。", "u": "b5c1.html"}, {"k": "探究與實作　1-1", "t": "過去、史料與歷史", "c": "三個不同的層次；為什麼會有不同版本", "u": "b5c1.html#s11"}, {"k": "探究與實作　1-2", "t": "史實、解釋與立場", "c": "可驗證的與可爭論的；史家的立場", "u": "b5c1.html#s12"}, {"k": "關鍵詞・探究與實作", "t": "史料", "c": "過去留下的痕跡，包括文字、器物、影像、口述與數據等。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "史實", "c": "可以被史料驗證的事實陳述，不因立場改變。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "史觀／歷史解釋", "c": "史家依據史料對事件成因、意義所提出的說明，可以被討論與挑戰。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "勝利者的歷史", "c": "指史料與敘事往往偏向有權力、識字或戰勝的一方，需要刻意尋找其他聲音。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "年鑑學派", "c": "二十世紀法國史學流派，主張跳脫政治事件，關注長時段結構與日常生活。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "社會史／庶民史", "c": "以一般人的生活經驗為研究對象，而非只寫菁英與政治人物。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "歷史意識", "c": "理解事物皆有其時間脈絡、並能據此判斷現況的能力。", "u": "b5c1.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "時代錯置", "c": "用今天的標準或概念去理解過去，忽略當時的脈絡。", "u": "b5c1.html#terms"}, {"k": "年代・十九世紀", "t": "蘭克學派強調依據原始檔案「如實直書」", "c": "探究與實作　歷史是什麼？", "u": "b5c1.html#timeline"}, {"k": "年代・二十世紀初", "t": "年鑑學派主張長時段、結構與日常生活的研究", "c": "探究與實作　歷史是什麼？", "u": "b5c1.html#timeline"}, {"k": "年代・1960 年代起", "t": "社會史、庶民史興起，關注過去被忽略的群體", "c": "探究與實作　歷史是什麼？", "u": "b5c1.html#timeline"}, {"k": "年代・1980 年代起", "t": "文化轉向、性別史、後殖民史學蓬勃發展", "c": "探究與實作　歷史是什麼？", "u": "b5c1.html#timeline"}, {"k": "年代・近二十年", "t": "環境史、全球史、數位人文成為新興取向", "c": "探究與實作　歷史是什麼？", "u": "b5c1.html#timeline"}, {"k": "探究與實作　第 2 章", "t": "選題", "c": "本章教你把模糊的興趣收斂成一個可研究的問題。好題目有三個條件：有明確的問題意識、有可取得的史料、在有限時間內做得完。我們會練習「漏斗法」：從大領域一路縮到具體提問，並學會分辨「可研究的問題」與「無法以史料回答的問題」。", "u": "b5c2.html"}, {"k": "探究與實作　2-1", "t": "什麼是好題目", "c": "三個必要條件；漏斗法：從大到小；常見的題目陷阱", "u": "b5c2.html#s21"}, {"k": "探究與實作　2-2", "t": "從個案到意義", "c": "小題目也能有大意義；先做可行性檢查", "u": "b5c2.html#s22"}, {"k": "關鍵詞・探究與實作", "t": "問題意識", "c": "研究者想弄清楚的具體疑問，決定整篇論文的方向與取材。", "u": "b5c2.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "漏斗法", "c": "從大領域逐層縮小到具體提問的選題方法。", "u": "b5c2.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "可行性檢查", "c": "在正式投入前，確認史料是否存在、可取得、讀得懂、做得完。", "u": "b5c2.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "假設性問題", "c": "如「若某事未發生會如何」，因無法以史料驗證，不適合作為研究題目。", "u": "b5c2.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "立場先行", "c": "先有結論再找證據，屬於研究倫理上的錯誤。", "u": "b5c2.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "個案研究", "c": "以具體而有限的對象進行深入分析，並回應較大的議題。", "u": "b5c2.html#terms"}, {"k": "年代・第 1 步", "t": "列出三個你真正好奇的方向", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "年代・第 2 步", "t": "各自用漏斗法縮到具體提問", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "年代・第 3 步", "t": "為每個提問做史料可行性檢查", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "年代・第 4 步", "t": "選定一題，寫成一句話的研究問題", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "年代・第 5 步", "t": "寫出 200 字研究動機與預期使用的史料", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "年代・第 6 步", "t": "與老師、組員討論後定案", "c": "探究與實作　選題", "u": "b5c2.html#timeline"}, {"k": "探究與實作　第 3 章", "t": "史料在哪裡？怎麼鑑別？", "c": "本章分兩部分。前半教你史料的種類與蒐集管道：從檔案館、圖書館、數位資料庫到田野與口述。後半教你鑑別：外部考證（這份東西是不是真的、何時何人所作）與內部考證（內容是否可信、作者有沒有理由說謊或誤記）。核心心法只有一句：孤證不立。", "u": "b5c3.html"}, {"k": "探究與實作　3-1", "t": "史料的種類與來源", "c": "一手與二手；常見的數位與實體管道", "u": "b5c3.html#s31"}, {"k": "探究與實作　3-2", "t": "鑑別史料", "c": "外部考證：這份材料本身可信嗎；內部考證：內容可信嗎；孤證不立與交叉驗證", "u": "b5c3.html#s32"}, {"k": "關鍵詞・探究與實作", "t": "一手史料", "c": "當時的人直接留下的材料，如檔案、日記、報紙、照片、器物、口述。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "二手史料", "c": "後人依據一手史料所做的研究與敘述。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "外部考證", "c": "鑑定史料本身的真偽、年代、作者與來源。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "內部考證", "c": "檢視史料內容是否可信，包括作者立場、資訊來源與內在一致性。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "孤證不立", "c": "只有單一材料支持的說法不能視為定論，須有其他材料佐證。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "交叉驗證", "c": "以不同性質、不同立場的材料互相印證，以提高可信度。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "口述歷史", "c": "以訪談方式蒐集當事人記憶的研究方法，須注意記憶偏差與知情同意。", "u": "b5c3.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "出處登錄", "c": "完整記錄史料的來源資訊，使他人能追溯查證。", "u": "b5c3.html#terms"}, {"k": "年代・步驟 1", "t": "先讀二手研究，掌握既有成果與脈絡", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 2", "t": "列出可能的一手史料類型", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 3", "t": "在資料庫與檔案機構檢索", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 4", "t": "實地查閱或申請調閱", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 5", "t": "外部考證：確認來源、年代、作者、真偽", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 6", "t": "內部考證：檢視立場、來源、一致性", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "年代・步驟 7", "t": "交叉驗證，登錄出處", "c": "探究與實作　史料在哪裡？怎麼鑑別？", "u": "b5c3.html#timeline"}, {"k": "探究與實作　第 4 章", "t": "關鍵詞／如何抓重點？", "c": "本章處理一個常被忽略卻致命的環節：界定關鍵詞。同一個詞在不同時代、不同立場的人口中意思可能完全不同；如果研究者沒有先講清楚自己怎麼用這個詞，整篇論文的論證都會鬆掉。本章教你辨識關鍵詞、追溯它的歷史用法、寫出操作型定義，並用它來檢索史料。", "u": "b5c4.html"}, {"k": "探究與實作　4-1", "t": "為什麼要界定關鍵詞", "c": "同一個詞，不同的意思；操作型定義", "u": "b5c4.html#s41"}, {"k": "探究與實作　4-2", "t": "抓重點的技術", "c": "從材料中抓出關鍵詞；用關鍵詞去檢索；做筆記的方法", "u": "b5c4.html#s42"}, {"k": "關鍵詞・探究與實作", "t": "關鍵詞", "c": "承載研究核心概念的語詞，決定檢索方向與論證邊界。", "u": "b5c4.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "操作型定義", "c": "在本篇研究中對關鍵詞的具體界定，說明包含什麼、排除什麼。", "u": "b5c4.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "時代錯置", "c": "用今天的詞義與價值理解過去，忽略當時的語境。", "u": "b5c4.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "當時用語", "c": "研究時代實際使用的詞彙，用以檢索才能找到對應史料。", "u": "b5c4.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "檢索式", "c": "由概念、地點、年代等條件組合而成的查詢語句。", "u": "b5c4.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "材料卡片", "c": "逐則記錄出處、原文摘錄與個人判讀的筆記方式。", "u": "b5c4.html#terms"}, {"k": "年代・第 1 步", "t": "從研究問題中圈出 3–5 個關鍵詞", "c": "探究與實作　關鍵詞／如何抓重點？", "u": "b5c4.html#timeline"}, {"k": "年代・第 2 步", "t": "查考這些詞在研究時代的用法", "c": "探究與實作　關鍵詞／如何抓重點？", "u": "b5c4.html#timeline"}, {"k": "年代・第 3 步", "t": "寫出本篇論文的操作型定義", "c": "探究與實作　關鍵詞／如何抓重點？", "u": "b5c4.html#timeline"}, {"k": "年代・第 4 步", "t": "以當時用語重新檢索史料", "c": "探究與實作　關鍵詞／如何抓重點？", "u": "b5c4.html#timeline"}, {"k": "年代・第 5 步", "t": "建立材料卡片，原文與解讀分欄記錄", "c": "探究與實作　關鍵詞／如何抓重點？", "u": "b5c4.html#timeline"}, {"k": "探究與實作　第 5 章", "t": "架構大綱與因果脈絡", "c": "本章教你把一堆材料組裝成一篇有論證的文章。重點有二：一是「架構」——用大綱把子問題排出先後與從屬關係；二是「因果」——分辨相關與因果、遠因近因導火線、必要條件與充分條件，並避開歷史論證中最常見的幾種謬誤。", "u": "b5c5.html"}, {"k": "探究與實作　5-1", "t": "從材料到大綱", "c": "大綱是論證的骨架；常見的組織方式", "u": "b5c5.html#s51"}, {"k": "探究與實作　5-2", "t": "因果關係的建立", "c": "分層看因果；必要條件與充分條件；常見的因果謬誤", "u": "b5c5.html#s52"}, {"k": "關鍵詞・探究與實作", "t": "大綱", "c": "以子問題與小結論排出的論證骨架，顯示推論的順序。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "遠因", "c": "長期存在的結構性條件，使事件有發生的可能。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "近因", "c": "直接促成事件的具體情勢。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "導火線", "c": "觸發事件的偶然事件，本身規模往往不大。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "必要條件", "c": "沒有它就不會發生，但有它也未必發生。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "充分條件", "c": "有了它就一定發生；歷史上極少存在。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "後此謬誤", "c": "誤以為先後發生即等於因果關係。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "單因論", "c": "把複雜事件化約為單一原因的錯誤。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "目的論", "c": "以結果回推，把歷史寫成必然走向現況的錯誤。", "u": "b5c5.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "社會達爾文主義", "c": "把生物演化的競爭邏輯誤用於人類社會與種族，曾被用來合理化殖民擴張。", "u": "b5c5.html#terms"}, {"k": "年代・第 1 步", "t": "把研究問題拆成 3–5 個子問題", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "年代・第 2 步", "t": "為每個子問題寫出一句話的小結論", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "年代・第 3 步", "t": "在每個小結論下列出支持材料", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "年代・第 4 步", "t": "選擇組織方式（時序／主題／比較／問題回應）", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "年代・第 5 步", "t": "檢查因果推論是否犯了常見謬誤", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "年代・第 6 步", "t": "定稿大綱，開始寫作", "c": "探究與實作　架構大綱與因果脈絡", "u": "b5c5.html#timeline"}, {"k": "探究與實作　第 6 章", "t": "歷史著作怎麼讀？歷史著作分析", "c": "本章是整學期的收束：學會有系統地分析一本歷史著作。從書名、目次、序言與注釋開始，判斷作者的問題意識、史料基礎、論證方式與侷限；並練習撰寫書評與研究回顧，把別人的成果轉化為自己研究的基礎。最後回到成果發表：如何把一學期的工作說清楚。", "u": "b5c6.html"}, {"k": "探究與實作　6-1", "t": "拆解一本歷史著作", "c": "先讀「書的骨架」；分析四問", "u": "b5c6.html#s61"}, {"k": "探究與實作　6-2", "t": "書評、研究回顧與發表", "c": "書評怎麼寫；研究回顧的功能；成果發表", "u": "b5c6.html#s62"}, {"k": "關鍵詞・探究與實作", "t": "問題意識（著作層次）", "c": "一本書想回答的核心問題，通常見於序言或導論。", "u": "b5c6.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "史料基礎", "c": "作者實際使用的材料種類與範圍，可從注釋與參考書目判斷。", "u": "b5c6.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "研究回顧", "c": "整理既有研究的成果與分歧，指出空白之處，藉以定位自己的研究。", "u": "b5c6.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "書評", "c": "客觀摘述著作內容並針對其論證提出具體評價的文章。", "u": "b5c6.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "不當引用", "c": "未標明出處而使用他人文字或觀點，屬學術倫理違失。", "u": "b5c6.html#terms"}, {"k": "關鍵詞・探究與實作", "t": "侷限說明", "c": "在論文中誠實交代研究未能處理的部分，是專業而非缺點。", "u": "b5c6.html#terms"}, {"k": "年代・讀書第 1 步", "t": "讀書名、目次、序言與注釋，判斷是否值得細讀", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・讀書第 2 步", "t": "以「分析四問」拆解全書", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・讀書第 3 步", "t": "寫成 500–800 字的書評", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・回顧第 1 步", "t": "蒐集 5–10 篇相關研究", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・回顧第 2 步", "t": "依觀點或取材分群，找出分歧與空白", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・回顧第 3 步", "t": "導向自己的研究問題", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}, {"k": "年代・發表", "t": "口頭報告與小論文投稿", "c": "探究與實作　歷史著作怎麼讀？歷史著作分析", "u": "b5c6.html#timeline"}];